// Документ об оценке соответствия по форме из графы 3 перечня.
const TR_FORM_LABEL={sert:'Сертификат соответствия ЕАЭС',dekl_only:'Декларация о соответствии ЕАЭС',dekl_sert:'Декларация о соответствии ЕАЭС или сертификат соответствия (по выбору заявителя)',gosreg:'Свидетельство о государственной регистрации',gosreg_dekl:'Свидетельство о государственной регистрации и декларация о соответствии (нужны оба документа)',dekl_gosreg:'Декларация о соответствии, или свидетельство о государственной регистрации, или сведения о государственной регистрации в едином реестре (любой из документов)',ottc:'Одобрение типа транспортного средства, одобрение типа шасси или свидетельство о безопасности конструкции транспортного средства',class:'Классификационное свидетельство',pasport:'Паспорт продукции, оформляемый изготовителем',none:'Форма в перечне не указана'};
function findTREAEU(q){
  const qn=norm(q);if(!qn||qn.length<4)return[];
  const res=[];
  for(const [trNum,tr] of Object.entries(TR_EAEU_DB)){
    for(const item of tr.items){
      const [num,name,codes,form,note]=item;
      for(const [code,partial] of codes){
        const cn=norm(code);
        if(cn.startsWith(qn)||qn.startsWith(cn.slice(0,Math.min(qn.length,10)))){
          res.push({trNum,trName:tr.name,act:tr.act,url:tr.url,transition:tr.transition,noList:tr.noList,num,name,code,partial,form,note});
          break;
        }
      }
    }
  }
  return res;
}


function findSert(q){
  const qn=norm(q);if(!qn||qn.length<4)return[];
  const seen=new Set(),res=[];
  for(const [code,name] of Object.entries(SERT_CODES)){
    const cn=norm(code);
    if(cn.startsWith(qn)||qn.startsWith(cn.slice(0,Math.min(qn.length,10)))){
      if(!seen.has(name)){seen.add(name);res.push({code,name})}
    }
  }
  return res;
}


