function findEECWaste(q){
  const qn=norm(q);if(!qn||qn.length<4)return[];
  const seen=new Set(),res=[];
  for(const [code,val] of Object.entries(EEC_WASTE)){
    const cn=norm(code);
    if(cn.startsWith(qn)||qn.startsWith(cn.slice(0,Math.min(qn.length,cn.length)))){
      // Код, общий для нескольких строк раздела 1.2 (3825, 3825 61 000 0, 7204 …), хранит
      // массив строк: у словаря «код → строка» остальные строки акта терялись.
      for(const [name,cat,exact] of Array.isArray(val[0])?val:[val]){
        const key=name+cat;
        if(!seen.has(key)){seen.add(key);res.push({code,name,cat,exact})}
      }
    }
  }
  return res;
}

// Направление разрешительного порядка — по заголовку Положения к Решению № 30 для раздела
// (PDF с eec.eaeunion.org, прочитаны 18.09.2026): 2.1 прил. 20, 2.2 прил. 11, 2.3 прил. 7, 2.4 прил. 12,
// 2.6 прил. 5, 2.8 прил. 6, 2.10 прил. 14, 2.11 прил. 4, 2.12 прил. 10, 2.13 прил. 19, 2.14 прил. 21,
// 2.16 прил. 15, 2.17 прил. 16, 2.19 прил. 9, 2.20 прил. 8, 2.21 прил. 3, 2.23 прил. 18, 2.30 прил. 22;
// 21.1 — Решение № 194 (ограничение экспорта). Раздел, чьё Положение не прочитано (2.9, 2.22), — оба направления.
const NTM_SEC_DIR={'2.1':'im ex tr','2.2':'im','2.3':'im ex tr','2.4':'ex','2.6':'ex','2.8':'ex','2.10':'im ex','2.11':'ex','2.12':'im ex','2.13':'im','2.14':'im','2.16':'im','2.17':'im ex','2.19':'im ex','2.20':'ex','2.21':'im ex','2.23':'ex','2.30':'im','21.1':'ex'};
const NTM_DIR_LABEL={'im':'при ввозе','ex':'при вывозе','im ex':'при ввозе и вывозе','im ex tr':'при ввозе, вывозе и транзите'};
// Что Положение раздела говорит о транзите (прочитано 18.09.2026): у 2.4, 2.6, 2.8, 2.20 и 2.30 помещение под
// реэкспорт и транзит — без лицензии/заключения; 2.1 и 2.3 транзит регулируют.
const NTM_SEC_TR={'2.1':'транзит озоноразрушающих веществ и содержащей их продукции регулируется Положением (приложение № 20 к Решению № 30)','2.3':'ввоз, вывоз и транзит опасных отходов идут через уведомление компетентного органа по Базельской конвенции от 22.03.1989 (приложение № 7 к Решению № 30)'};
const NTM_DIR_REQ={'im':'Ввоз','ex':'Вывоз','im ex':'Ввоз и вывоз','im ex tr':'Ввоз и вывоз'};
function ntmRegime(section){
  if(section.startsWith('21'))return'quota';
  if(section.startsWith('1.')||section==='1')return'ban';
  return'license';
}
function ntmDir(name){
  const hasIm=/ввоза|ввоз(?!а)/i.test(name)&&!/вывоз/i.test(name.replace(/ввоз[а-я]*/i,''));
  const imWord=/ввоз/i.test(name),exWord=/вывоз/i.test(name);
  if(imWord&&!exWord)return'import';
  if(exWord&&!imWord)return'export';
  return'both';
}
function findEEC30(q){
  const qn=norm(q);if(!qn||qn.length<4)return[];
  const seen=new Set(),res=[];
  for(const [section,name,codes,flag,note] of NTM_DB){
    if(!codes||!codes.length)continue;
    for(const code of codes){
      const cn=norm(code);
      if(!cn)continue;
      if(cn.startsWith(qn)||qn.startsWith(cn.slice(0,Math.min(qn.length,cn.length)))){
        const key=section+name;
        if(!seen.has(key)){
          seen.add(key);
          res.push({code,name,section,dir:ntmDir(name),regime:ntmRegime(section),note:note||null,partial:cn.length<=4});
        }
        break;
      }
    }
  }
  return res;
}

