function findETTUAE(q){
  const qn=norm(q).replace(/\D/g,'');
  if(!qn||qn.length<4)return[];
  const direct=ETT_UAE_DB.filter(r=>r[0].startsWith(qn));
  if(direct.length)return direct;
  // Прямых совпадений нет — возможно, позиция записана в приложении к
  // Соглашению в старой редакции номенклатуры. Копируем строку и помечаем,
  // чтобы карточка вышла с предупреждением (см. render()).
  const out=[];
  for(const L of legacyMapFor(ETT_UAE_DB,r=>r[0]).values()){
    if(!legacyAppliesTo(L.at,qn))continue;
    const rr=L.row.slice();rr.legacy=true;rr.legacyAt=L.at;out.push(rr);
  }
  return out;
}
