function findETTVN(q){
  const qn=norm(q).replace(/\D/g,'');
  if(!qn||qn.length<4)return[];
  return ETT_VN_DB.filter(r=>r[0].startsWith(qn)||qn.startsWith(r[0]));
}


function ettSplitName(code,name){
  // Некоторые товарные позиции ЕТТ (напр. 8516, 9405) официально объединяют много разных
  // изделий под одним длинным заголовком — специфичная часть обычно в конце строки.
  // Находим общий префикс среди всех кодов той же 4-значной позиции и выделяем хвост.
  const heading=code.slice(0,4);
  const siblings=ETT_DB.filter(r=>r[0].slice(0,4)===heading);
  if(siblings.length<3)return{prefix:'',unique:name};
  let prefix=siblings[0][1];
  for(const r of siblings){
    let i=0;
    while(i<prefix.length&&i<r[1].length&&prefix[i]===r[1][i])i++;
    prefix=prefix.slice(0,i);
  }
  if(prefix.length<60||prefix.length>=name.length-5)return{prefix:'',unique:name};
  return{prefix:name.slice(0,prefix.length),unique:name.slice(prefix.length)};
}
function ettNameHtml(code,name){
  const{prefix,unique}=ettSplitName(code,name);
  if(!prefix)return esc(name);
  return `<span style="color:var(--muted)">${esc(prefix)}</span><strong>${esc(unique)}</strong>`;
}
function ettNameRowHtml(code,name){
  const{prefix,unique}=ettSplitName(code,name);
  if(!prefix)return esc(trunc(name,90));
  return `<span style="color:var(--muted)">…</span><strong>${esc(trunc(unique,90))}</strong>`;
}
function findETT(q){
  const qn=norm(q).replace(/\D/g,'');
  if(!qn||qn.length<4)return[];
  return ETT_DB.filter(r=>r[0].startsWith(qn));
}
