// Диапазон кодов («1517 – 1522 00», «4407 21 – 4407 29») сравнивается по
// префиксам равной длины — так он работает и когда запрос короче границы
// диапазона, и когда длиннее.
function prefRangeHit(a,b,q){
  const na=Math.min(q.length,a.length),nb=Math.min(q.length,b.length);
  return q.slice(0,na)>=a.slice(0,na)&&q.slice(0,nb)<=b.slice(0,nb);
}
function prefHit(c,q){
  const d=c.indexOf('-');
  if(d>0)return prefRangeHit(c.slice(0,d),c.slice(d+1),q);
  return c.startsWith(q)||q.startsWith(c);
}
// Исключение снимает преференцию только тогда, когда запрошенный код лежит
// внутри исключения. Обратный случай — исключение уже запроса — означает, что
// по группе преференция есть, но не по этим кодам, и их надо перечислить,
// а не гасить всю позицию.
function prefExcCovers(c,q){
  const d=c.indexOf('-');
  if(d>0){const a=c.slice(0,d),b=c.slice(d+1);return q.length>=Math.min(a.length,b.length)&&prefRangeHit(a,b,q)}
  return q.length>=c.length&&q.startsWith(c);
}
function findPref(q){
  const qn=norm(q).replace(/\D/g,'');
  if(!qn||qn.length<2)return[];
  const out=[];
  for(const row of PREF_GOODS){
    const inc=row[1].split(',');
    let hit=null;
    for(const c of inc){if(prefHit(c,qn)){hit=c;break}}
    if(!hit)continue;
    const exc=row[2]?row[2].split(','):[];
    const ex=[],exPart=[];
    for(const e of exc){
      if(prefExcCovers(e,qn))ex.push(e);
      else if(prefHit(e,qn))exPart.push(e);
    }
    out.push({sec:row[0],inc:hit,incAll:inc,name:row[3],fn:row[4]===1,ex:ex,exPart:exPart});
  }
  return out;
}
function prefFmt(c){return c.length<=4?c:(c.slice(0,4)+' '+c.slice(4,6)+(c.length>6?' '+c.slice(6,9):'')+(c.length>9?' '+c.slice(9):'')).trim()}
function prefCodeList(a,n){
  const shown=a.slice(0,n).map(c=>c.indexOf('-')>0?prefFmt(c.slice(0,c.indexOf('-')))+' – '+prefFmt(c.slice(c.indexOf('-')+1)):prefFmt(c)).join(', ');
  return a.length>n?shown+' и ещё '+(a.length-n):shown;
}

function prefPlural(n,one,few,many){const d=n%10,dd=n%100;return n+' '+(d===1&&dd!==11?one:(d>=2&&d<=4&&(dd<12||dd>14)?few:many))}
// Страна зоны свободной торговли СНГ (LK_CIS в checker.js): ввозная пошлина не применяется ни к одному коду,
// поэтому карточка не отсылает к перечню, а говорит об условии — происхождении, подтверждённом сертификатом.
function cisCountryHtml(x){
  const src=x.doc==='krAzFta'
    ?`${docLink('Соглашение между Правительством КР и Правительством Азербайджанской Республики о свободной торговле от 12.01.2004 — реестр Минюста КР',DOC_SOURCES.krAzFta)}; ${docLink('Закон КР от 02.03.2006 № 72 о его ратификации',DOC_SOURCES.krLaw72)}; ${docLink('Договор о ЕАЭС от 29.05.2014, п.1 ст.102',DOC_SOURCES.eaeuTreaty)}; ${docLink('Закон КР «О таможенном тарифе» от 30.12.2014 № 173, ст.8',DOC_SOURCES.krTariffLaw)}`
    :x.doc==='cisFtaUz'
    ?`${docLink('Протокол о применении Договора о зоне свободной торговли между его Сторонами и Республикой Узбекистан от 31.05.2013 — Закон КР от 01.03.2017 № 37 о его ратификации (реестр Минюста КР)',DOC_SOURCES.krLaw37)}`
    :`${docLink('Договор о зоне свободной торговли от 18.10.2011 — Закон КР от 09.12.2013 № 212 о его ратификации (реестр Минюста КР)',DOC_SOURCES.krLaw212)}; ${docLink('Соглашение о Правилах определения страны происхождения товаров в СНГ от 20.11.2009 (в ред. Протокола от 31.05.2019, форма СТ-1) — реестр Минюста КР',DOC_SOURCES.cisOrigin)}`;
  return `<div class="card c-ett"><div class="rh"><div class="ico">${x.flag}</div><div><div class="rc">${esc(x.n)}</div></div></div>`
    +`<div class="rn">${x.bilateral?'Двустороннее соглашение о свободной торговле':'Зона свободной торговли СНГ'}: ввозная пошлина не применяется к товарам, происходящим из этой страны</div>`
    +`<div class="tags"><span class="tag t-ok">0% — пошлина не взимается</span></div>`
    +`<div class="det">Основание: ${esc(x.act)}; ${x.bilateral?'временно применяется со дня подписания (ст.13 Соглашения) — с':'для Кыргызской Республики — с'} ${lkDateRu(x.from)}. ${x.bilateral?'Изъятий по номенклатуре Соглашение не содержит (по ст.1 исключения оформляются протоколами, если Стороны сочтут это необходимым; таких протоколов в реестре Минюста КР нет), поэтому ставка 0% — по любому коду ТН ВЭД. Соглашение заключено до вступления Кыргызской Республики в ЕАЭС: по п.1 ст.102 Договора о ЕАЭС государство-член вправе в одностороннем порядке предоставлять преференции по такому договору, а подп.1 п.1 ст.8 Закона КР «О таможенном тарифе» освобождает от пошлины товары из государств, образующих с Кыргызской Республикой зону свободной торговли. Применение преференции к конкретной поставке подтверждает таможенный орган.':'Изъятий у Кыргызской Республики нет, поэтому ставка 0% — по любому коду ТН ВЭД.'}<br>`
    +`<strong>Условие:</strong> товар происходит из этой страны, и происхождение подтверждено — ${esc(x.orig)}. Страна продавца или отправления происхождения не доказывает.<br>`
    +`НДС, акцизы, запреты, лицензии, сертификация и контроль на границе применяются как при обычном ввозе — введите код ТН ВЭД, чтобы увидеть их.<br>`
    +`<strong>Источники:</strong> ${src}.${auditNote('cis')}</div></div>`;
}
function prefCountryHtml(q,list){
  const nDev=PREF_GOODS.filter(r=>r[0]===0).length, nLdc=PREF_GOODS.filter(r=>r[0]===1).length;
  let html='';
  for(const c of list.slice(0,8)){
    const head=[],blocks=[];
    if(c.dev){
      head.push('75% от ставки ЕТТ');
      blocks.push(`<div class="usir-row"><div class="un">Развивающаяся страна — пользователь ЕСТП</div><div class="uu">Ставка ввозной пошлины — <strong>75% от ставки ЕТТ</strong> (пункт 2 статьи 36 Договора о ЕАЭС), но только по товарам из раздела I перечня преференциальных товаров: ${prefPlural(nDev,'позиция','позиции','позиций')}. Перечень стран — приложение 2 к Решению КТС №130 в редакции Решения Совета ЕЭК №8 от 28.01.2026.</div></div>`);
    }
    if(c.ldc){
      head.push('0% — пошлина не взимается');
      blocks.push(`<div class="usir-row"><div class="un">Наименее развитая страна — пользователь ЕСТП</div><div class="uu">Ставка ввозной пошлины — <strong>0%</strong> (пункт 3 статьи 36 Договора о ЕАЭС), но только по товарам из раздела II перечня преференциальных товаров: ${prefPlural(nLdc,'позиция','позиции','позиций')}. Перечень стран — приложение 3 к Решению КТС №130 в редакции Решения Совета ЕЭК №8 от 28.01.2026.</div></div>`);
    }
    if(c.fta){
      head.push('своё соглашение с ЕАЭС');
      blocks.push(`<div class="usir-row"><div class="un">${esc(c.fta.t)}</div><div class="uu">${esc(c.fta.d)}</div>${c.fta.w?`<div class="uu" style="color:var(--orange)">⚠️ ${esc(c.fta.w)}</div>`:''}</div>`);
    }
    const estp=c.dev||c.ldc;
    const cond=estp?`<div class="det"><strong>Преференция ЕСТП даётся не стране, а товару этой страны.</strong> По пункту 65 Правил определения происхождения одновременно должны выполняться четыре условия: товар включён в перечень преференциальных товаров; происхождение подтверждено сертификатом по форме приложения № 2 к Правилам (срок применения — 12 месяцев с даты выдачи), а при таможенной стоимости партии не более 5 000 евро — декларацией о происхождении товара; соблюдено требование прямой поставки (пункты 67–70); страна-пользователь соблюдает требования административного сотрудничества. Прямой закупки не требуется: по пункту 66 товар можно купить и у лица, зарегистрированного в любой другой стране. Критерий достаточной переработки — не более ${c.dev&&!c.ldc?'50':(c.ldc&&!c.dev?'60':'50 (для развивающихся) или 60 (для наименее развитых)')}% стоимости непроисходящих материалов на условиях «франко-завод».<br><strong>Чтобы узнать ставку по своему товару, введите его код ТН ВЭД</strong> — карточка «Преференция ЕСТП» покажет, входит ли код в перечень и что по нему получается.<br><strong>Источники:</strong> ${docLink('пункты 2 и 3 статьи 36 Договора о ЕАЭС от 29.05.2014',DOC_SOURCES.eaeuTreaty)}; ${docLink('перечень преференциальных товаров (сводная публикация ЕЭК на 08.03.2026)',DOC_SOURCES.prefGoods)}; ${docLink('перечни стран (сводная публикация ЕЭК от 15.05.2026)',DOC_SOURCES.prefCountries)}; ${docLink('Правила определения происхождения',DOC_SOURCES.prefRules)}.${auditNote('pref')}</div>`
      :`<div class="det">Ставка зависит от кода товара — введите код ТН ВЭД, и карточка соглашения покажет, что по нему действует. Преференция применяется только к товарам, ПРОИСХОДЯЩИМ из этой страны, и требует сертификата происхождения по соответствующему соглашению.</div>`;
    html+=`<div class="card c-ett"><div class="rh"><div class="ico">🌍</div><div><div class="rc">${esc(c.name)}</div></div></div><div class="rn">${estp?'Страна — пользователь единой системы тарифных преференций ЕАЭС'+(c.fta?', и с ней же действует собственное соглашение с ЕАЭС':''):'Действует '+esc(c.fta.t)}</div><div class="tags"><span class="tag t-ett">🌍 Преференция по стране</span></div>${estp?`<div class="ett-rate">${esc(head.filter(h=>h!=='своё соглашение с ЕАЭС').join(' · '))}</div>`:''}<div class="usir-list">${blocks.join('')}</div>${cond}</div>`;
  }
  if(list.length>8)html+=`<div class="card c-ett"><div class="rn">Показаны первые 8 из ${list.length} совпавших стран — уточните запрос.</div></div>`;
  return html;
}
const NPA_REGISTRY_URL='https://www.gov.kg/ru/npa/c/provisions';
