function nksCat(c){
  if(NKS_ITCAT[c])return{name:NKS_ITCAT[c][0],sec:NKS_ITCAT[c][1],ico:NKS_ITCAT[c][2]};
  const p4=c.slice(0,4),p7=c.slice(0,7);
  if(p7==='3002905'||p7==='3002909') return{name:'Биологические агенты и токсины',sec:'НКС — Список 1 (биологические агенты)',ico:'🧬'};
  if(['2844','2845','2846','2848','2849','2850','2853'].includes(p4)) return{name:'Ядерные и радиоактивные материалы',sec:'НКС — Ядерный список',ico:'☢️'};
  if(['3601','3602','3603','3604','3606'].includes(p4)) return{name:'Взрывчатые вещества и воспламенители',sec:'НКС — Взрывчатые вещества',ico:'💣'};
  if(['8802','8803'].includes(p4)) return{name:'Летательные аппараты и части',sec:'НКС — Авиационная техника',ico:'✈️'};
  if(p4==='8401') return{name:'Ядерные реакторы и оборудование',sec:'НКС — Ядерный список',ico:'⚛️'};
  if(p4==='9306') return{name:'Боеприпасы и взрывные устройства',sec:'НКС — Военный список',ico:'🎯'};
  if(['8905','8906','8907'].includes(p4)) return{name:'Суда спец. назначения',sec:'НКС — Двойное назначение',ico:'🚢'};
  const ch=['2710','2804','2805','2808','2811','2812','2813','2818','2825','2826','2827','2829','2830','2833','2834','2835','2836','2837','2839','2841','2842','2901','2902','2903','2904','2905','2909','2914','2915','2918','2920','2921','2922','2925','2928','2929','2930','2931','2933','2934','3212'];
  if(ch.includes(p4)) return{name:'Химикаты, прекурсоры химического оружия',sec:'НКС — Химический список (КХО)',ico:'⚗️'};
  return{name:'Оборудование и материалы двойного назначения',sec:'НКС — Двойное назначение',ico:'🔧'};
}

