// Обозначение знака в реестре часто нарисовано, а не написано: в 172 записях
// текстом есть только вид знака, ещё в 18 нет и его. Поэтому строка записи
// всегда несёт охранный документ (свидетельство Кыргызпатента или регистрация
// ВОИС) и ссылку на страницу самого реестра — по ним знак опознаётся, даже
// когда его название в базу вытащить неоткуда.
function troisPageLink(pg){
  if(!pg)return '';
  return `<a class="lb-skip" href="${esc(DOC_SOURCES.trois)}#page=${pg}" target="_blank" rel="noopener" style="color:inherit;text-decoration:underline">изображение знака — стр. ${pg} реестра</a>`;
}
function troisRowHtml(rec,codeRaw){
  const no=rec[0],rd=rec[1],mk=rec[2],st=rec[3],a=rec[4],end=rec[5],dv=rec[6],hold=rec[7],ord=rec[8],codes=rec[9],doc=rec[10],pg=rec[11];
  const badge=st===0?'<span style="color:var(--muted)">исключён из реестра</span>':(a?'<span style="color:var(--red);font-weight:600">в реестре</span>':'<span style="color:var(--muted)">срок внесения истёк</span>');
  const term=end?((dv?'расчётный срок — до ':'срок — до ')+end):'срок в реестре не указан';
  let codeLine;
  if(codeRaw){
    const gt=codeRaw.indexOf('>');
    const shown=gt<0?codeRaw:codeRaw.slice(0,gt);
    const mapped=gt<0?'':' (в действующем ЕТТ такого кода нет, сопоставлен с '+esc(fmtCode(codeRaw.slice(gt+1)))+')';
    codeLine='Код в реестре: '+esc(shown.length===2?('группа '+shown):fmtCode(shown))+mapped;
  }else{
    const list=codes.slice(0,10).map(c=>{const g=c.indexOf('>'),cc=g<0?c:c.slice(0,g);
      return cc.length===2?('группа '+esc(cc)):`<span style="cursor:pointer;text-decoration:underline" onclick="goToCode('${g<0?cc:c.slice(g+1)}')">${esc(fmtCode(cc))}</span>`}).join(', ');
    codeLine='Коды ТН ВЭД: '+(list||'в реестре не указаны')+(codes.length>10?' и ещё '+(codes.length-10):'');
  }
  return `<div class="usir-row"><div class="un">№${esc(no)}/ТЗ${rd?' от '+esc(rd):''} — ${esc(mk||'обозначение в реестре приведено изображением')} — ${badge}</div><div class="uu">${codeLine} · ${esc(term)}${ord?' · '+esc(ord):''}</div><div class="uu">Правообладатель: ${esc(hold)}</div><div class="uu">${doc?esc(doc):'охранный документ в реестре не указан'}${pg?' · '+troisPageLink(pg):''}</div></div>`;
}
function troisDetHtml(){
  return `<div class="det"><strong>Что это значит:</strong> при обнаружении товаров с товарным знаком, внесённым в реестр, таможенный орган приостанавливает выпуск на срок до 10 рабочих дней и не позднее следующего рабочего дня уведомляет декларанта и правообладателя; по запросу правообладателя срок продлевается ещё не более чем на 10 рабочих дней. Выпуск не приостанавливается, если правообладатель или его представитель дал письменное согласие на ввоз (п.12 Положения). Это не запрет ввоза: нужен документ от правообладателя либо статус санкционированного импортёра.<div style="margin-top:8px"><strong>Совпадение по коду — не совпадение по знаку.</strong> Реестр охраняет обозначение, а не код: карточка появляется, когда код товара попадает в перечень кодов записи, но мера применяется только к товарам, маркированным именно этим знаком. Там, где реестр указал группу целиком («группа 22» по алкоголю), совпадение заведомо широкое.</div><div style="margin-top:8px"><strong>Если обозначение не названо словами</strong>, значит в реестре оно приведено картинкой — тогда запись опознаётся по охранному документу и по странице реестра, ссылка на которую стоит в строке.</div><div style="margin-top:8px">Перечни доверенных лиц и санкционированных импортёров в базу не перенесены — это персональные данные и телефоны конкретных людей; смотрите их в самом реестре.</div><div style="margin-top:8px"><strong>Правовая основа:</strong> ${docLink('Положение о порядке таможенного контроля в отношении товаров, содержащих объекты интеллектуальной собственности',DOC_SOURCES.troisPol)}, утверждённое ${docLink('постановлением Правительства КР от 27 ноября 2000 года № 694',DOC_SOURCES.trois694)} (действует, редакция 23.04.2015).</div><div style="margin-top:8px"><strong>Источник данных:</strong> ${docLink('Таможенный реестр объектов интеллектуальной собственности ГТС на 21.08.2026',DOC_SOURCES.trois)} — раздел ${docLink('«Защита прав интеллектуальной собственности»',DOC_SOURCES.troisPage)} на сайте ГТС при Минфине КР.</div>${auditNote('trois')}</div>`;
}
// Поиск по названию знака. Реестр — единственная база в файле, где искать по
// имени осмысленнее, чем по коду: пользователь знает бренд, а не код товара.
// Правообладатель тоже ищется, но с более длинного запроса — короткие подстроки
// («ао», «инк») совпадают с доброй половиной названий компаний.
function findTROISByName(q){
  const qq=(q||'').trim().toLowerCase();
  if(qq.length<2||/^[\d\s.]+$/.test(qq))return[];
  const res=[];
  for(const rec of TROIS_DB){
    const mk=(rec[2]||'').toLowerCase();
    let where='';
    if(mk&&mk.charAt(0)!=='('&&mk.indexOf(qq)>=0)where='mk';
    else if(qq.length>=4&&(rec[7]||'').toLowerCase().indexOf(qq)>=0)where='hold';
    if(where)res.push({rec:rec,where:where});
  }
  res.sort((x,y)=>(x.where===y.where?0:(x.where==='mk'?-1:1))||(y.rec[4]-x.rec[4])||(x.rec[0]<y.rec[0]?-1:1));
  return res;
}
function troisNameHtml(qq,list){
  const shown=list.slice(0,25);
  const nAct=list.filter(h=>h.rec[4]===1).length;
  let rows='';
  for(const h of shown)rows+=troisRowHtml(h.rec,'');
  const more=list.length>shown.length?`<div class="uu" style="margin-top:8px">Показаны первые ${shown.length} из ${list.length} — уточните запрос.</div>`:'';
  const tg=nAct>0?'<span class="tag t-srt">🛡️ Товарный знак в ТРОИС</span>':'<span class="tag t-usir">🛡️ ТРОИС — записи недействующие</span>';
  return `<div class="card c-srt"><div class="rh"><div class="ico">🛡️</div><div><div class="rc">${esc(qq)}</div></div></div><div class="rn">В таможенном реестре ОИС найдено записей по названию: ${list.length}${nAct>0?', из них действующих: '+nAct:' (действующих нет)'}</div><div class="tags">${tg}</div><div class="usir-list">${rows}${more}</div>${troisDetHtml()}</div>`;
}
function findTROIS(q){
  const qn=norm(q);if(!qn||qn.length<4)return[];
  const res=[];
  for(const rec of TROIS_DB){
    let hit='';
    for(const raw of rec[9]){
      const gt=raw.indexOf('>'),c=gt<0?raw:raw.slice(gt+1);
      if(c.length===2){if(qn.slice(0,2)===c){hit=raw;break}continue}
      if(c.startsWith(qn)||qn.startsWith(c)){hit=raw;break}
    }
    if(hit)res.push({rec:rec,code:hit});
  }
  res.sort((x,y)=>(y.rec[4]-x.rec[4])||(x.rec[0]<y.rec[0]?-1:1));
  return res;
}
function findTrigger(q){
  const qn=norm(q);if(!qn||qn.length<4)return[];
  const res=[];
  for(const rec of TRIGGER_DB){
    const codes=rec[0];
    if(codes.some(c=>c.startsWith(qn)||qn.startsWith(c))) res.push(rec);
  }
  return res;
}
function findQuota(q){
  const qn=norm(q);if(!qn||qn.length<4)return[];
  const res=[];
  for(const rec of QUOTA_DB){
    const codes=rec[0];
    if(codes.some(c=>c.startsWith(qn)||qn.startsWith(c))) res.push(rec);
  }
  return res;
}
