// Мера ищется по коду в обе стороны, как и всюду в файле. Диапазон сравнивается
// префиксами равной длины — это работает и когда запрос длиннее концов диапазона,
// и когда короче. Исключение снимает попадание только тогда, когда запрос не короче
// самого исключения: по более общему коду мера частью товаров всё ещё действует.
// Признак «действует» (r[13]) снят с реестра на дату его состояния (UNIMEAS_ASOF). Мера, чей срок
// «до/по ДД.ММ.ГГГГ» с тех пор прошёл, действующей больше не считается: на 17.09.2026 так оставались
// «действующими» пять кыргызских запретов, истёкших 01–15.09.2026. today — для тестов.
// Мера с датой начала «с ДД.ММ.ГГГГ» до этой даты не действует (нужно для проверки на прошлую дату).
function umStarted(srok,today){
  const m=/(?:^|\s)с\s+(\d{2})\.(\d{2})\.(\d{4})/.exec(String(srok||''));
  if(!m)return true;
  const d=today||new Date(Date.now()+6*3600e3).toISOString().slice(0,10);
  return m[3]+'-'+m[2]+'-'+m[1]<=d;
}
function umTermEnded(srok,today){
  const ends=[...String(srok||'').matchAll(/(?:до|по)\s+(\d{2})\.(\d{2})\.(\d{4})/g)].map(m=>m[3]+'-'+m[2]+'-'+m[1]);
  const d=today||new Date(Date.now()+6*3600e3).toISOString().slice(0,10);
  return ends.length>0&&ends.every(e=>e<d);
}
function findUniMeasure(q,today){
  const qn=norm(q); if(!qn||qn.length<4) return [];
  const res=[];
  for(const r of UNIMEAS_DB){
    const inc=r[6],exc=r[7],rng=r[8],part=r[9];
    let hit=null;
    for(const c of inc){ if(c.startsWith(qn)||qn.startsWith(c)){ hit=c; break; } }
    if(!hit){
      for(const pair of rng){
        const a=pair[0],b=pair[1],L=Math.min(qn.length,a.length);
        const p=qn.slice(0,L);
        if(p>=a.slice(0,L)&&p<=b.slice(0,L)){ hit=a+'-'+b; break; }
      }
    }
    if(!hit) continue;
    let dropped=false;
    for(const e of exc){ if(qn.length>=e.length&&qn.startsWith(e)){ dropped=true; break; } }
    if(dropped) continue;
    res.push({cc:r[0],year:r[1],n:r[2],mera:r[3],tovar:r[4],codesTxt:r[5],
      srok:r[10],osn:r[11],prot:r[12],act:r[13]===1&&!umTermEnded(r[10],today)&&umStarted(r[10],today),
      part:part.some(c=>c.startsWith(qn)||qn.startsWith(c)),code:hit});
  }
  return res;
}
// Перечень организаций-экспертов и уполномоченных органов КР — приложение к
// постановлению Правительства КР от 20.04.2021 № 156 (ред. ПКМ КР № 218 от 02.04.2026).
// Позиция 2.7 (СИТЕС) в этот перечень не входит и взята из отдельного акта — см. r[4].
const PERMIT_ACT='Постановление Правительства КР от 20.04.2021 № 156 (ред. от 02.04.2026)';
function permitOrgByPos(pos){
  const r=PERMIT_ORGS.find(x=>x[0]===pos);
  return r?{pos:r[0],tovar:r[1],org:r[2],upOrg:r[3],src:(r[4]&&typeof r[4]==='object')?r[4]:null}:null;
}
// Источник позиции: по умолчанию — само постановление № 156, иначе акт из r[4].
function permitSrcHtml(src){
  return src?`<div class="more-hint">${docLink(src.a,DOC_SOURCES[src.k])}. ${esc(src.m)}</div>`:'';
}
// Блок «кто выдаёт документ в КР» для карточки Единого перечня: по строке на каждый
// раздел, попавший в выдачу. Разделы, которых в перечне нет, названы отдельно — иначе
// карточка выглядит полной, не будучи ею.
// Разделы 2.19 и 2.16: кроме лицензии и заключения Положения признают третье основание —
// запись в едином реестре ЕАЭС (ЕС НСИ № 1994 и № 1992). Текст — по сводным редакциям ЕЭК
// приложений № 9 (ред. Решения № 69 от 18.06.2024; с 28.09.2025 Решением № 75 исключён абзац о
// «запасных частях» в Положении о нотификации) и № 15 (ред. Решения № 68 от 07.07.2025), прочитаны 24.09.2026.
function ntmRegistryHtml(sections){
  let h='';
  if(sections.includes('2.19'))h+=`<div><strong>Нотификация:</strong> вместо лицензии или заключения достаточно сведений о нотификации, включённой в ${docLink('единый реестр нотификаций ЕАЭС','https://nsi.eaeunion.org/portal/1994')} (п. 5 ${docLink('Положения — приложение № 9 к Решению № 30','https://eec.eaeunion.org/upload/medialibrary/299/6km9eqf2eu90b49t2r69612x2eean220/pr9_69.pdf')}). Нотифицировать можно только товары 12 категорий приложения № 4: массовые товары с недоступной пользователю криптографией, банковские и SIM-карты, мобильные устройства без сквозного шифрования, беспроводное оборудование с дальностью до 400 м и др.; прочие шифровальные средства — по лицензии или заключению. Физическим лицам для личного пользования документы не нужны для товаров приложения № 5 (компьютеры и смартфоны с массовым ПО, банковские и SIM-карты, сотовые телефоны без сквозного шифрования, принтеры, роутеры), остальное — только при наличии нотификации.</div>`;
  if(sections.includes('2.16'))h+=`<div><strong>Единый реестр РЭС и ВЧУ:</strong> ввоз допускается и без лицензии или заключения, если устройство включено в ${docLink('единый реестр РЭС и ВЧУ ЕАЭС','https://nsi.eaeunion.org/portal/1992')} (п. 4 ${docLink('Положения — приложение № 15 к Решению № 30','https://eec.eaeunion.org/upload/medialibrary/794/vtlhhj3e8kox3rzx6gxxz3uue8ux8mos/PR15_68.pdf')}), а устройства приложения № 2 (бытовые СВЧ- и индукционные печи, мобильные телефоны и модемы, маломощные радиостанции и др.) ввозятся вовсе без документов. Физическим лицам для личного пользования реестр или приложение № 2 заменяют заключение. Шифровальные функции в устройстве дополнительно требуют заключения или нотификации по разделу 2.19.</div>`;
  return h;
}
function permitOrgHtml(sections){
  const found=[],miss=[];
  for(const p of sections){const r=permitOrgByPos(p);if(r)found.push(r);else miss.push(p);}
  if(!found.length&&!miss.length)return'';
  const li=found.map(r=>{
    const body=r.org===r.upOrg
      ?`${esc(r.org)} — и экспертное заключение, и разрешительный документ`
      :`экспертное заключение — ${esc(r.org)}; разрешительный документ (лицензию) — ${esc(r.upOrg)}`;
    return `<li><strong>п. ${esc(r.pos)}</strong> — ${body}${permitSrcHtml(r.src)}</li>`;
  }).join('');
  const missHtml=miss.length?`<div class="more-hint">Для раздел${miss.length===1?'а':'ов'} ${esc(miss.join(', '))} орган перечнем не назван — уточните в Министерстве экономики и коммерции КР.</div>`:'';
  const src=`<div class="more-hint">${docLink(PERMIT_ACT,DOC_SOURCES.permit156)} — Перечень организаций-экспертов по выдаче экспертного заключения и уполномоченных органов по выдаче разрешительных документов.</div>`;
  return `<div><strong>Кто выдаёт документ в Кыргызстане:</strong>${li?`<ul class="note-list">${li}</ul>`:''}${missHtml}${src}${auditNote('permit')}</div>`;
}
// Запрет со сроком: exFrom/imFrom — первый день, exUntil/imUntil — последний (включительно). Вне срока
// запрет не считается действующим: истёкший продлевается новым постановлением, и пока его нет в базе,
// красный «Запрет» вводил бы в заблуждение. today — дата по Бишкеку, параметр нужен тестам.
function banOn(e,side,today){
  if(!e[side])return false;
  const d=today||new Date(Date.now()+6*3600e3).toISOString().slice(0,10);
  const from=e[side+'From'],until=e[side+'Until'];
  return !(from&&d<from)&&!(until&&d>until);
}
function findBan(q){
  const qn=norm(q);if(!qn)return[];
  return BAN_DB.filter(e=>e.codes.some(c=>{const cn=norm(c);return cn.startsWith(qn)||qn.startsWith(cn)}));
}

