// Прослеживаемость ЕАЭС (Решение Совета ЕЭК № 5 от 26.01.2026, механизм — с 01.09.2026 по
// решению Межправсовета № 5 от 30.09.2025; в КР — ПКМ № 613 от 14.09.2026, ЭСФ 2.0): не
// маркировка, а учёт после выпуска. Строка: [группа, коды, с какой даты, акты, ссылка].
const TRACE_DB=[["Холодильники и морозильники бытовые",["8418102001","8418108001","8418211000","8418215100","8418215900","8418219100","8418219900","8418290000","8418302001","8418308001","8418402001","8418408001"],"2026-09-01","Решение Совета ЕЭК от 26.01.2026 № 5 (перечень); Решение Евразийского межправсовета от 30.09.2025 № 5 (вступило 01.09.2026); ПКМ КР от 14.09.2026 № 613","https://docs.eaeunion.org/documents/461/10465/"],["Машины стиральные, бытовые или для прачечных, включая машины, оснащенные отжимным устройством",["8450111100","8450111900","8450119000","8450120000","8450190000","8450200000"],"2026-09-01","Решение Совета ЕЭК от 26.01.2026 № 5; ПКМ КР от 14.09.2026 № 613","https://docs.eaeunion.org/documents/461/10465/"],["Аппаратура приемная для телевизионной связи, включающая или не включающая в свой состав широковещательный радиоприемник или аппаратуру, записывающую или воспроизводящую звук или изображение",["8528711100","8528711500","8528711900","8528719100","8528719900","8528721000","8528722001","8528722009","8528723001","8528723002","8528723003","8528723009","8528724000","8528726000","8528728000","8528730000"],"2026-09-01","Решение Совета ЕЭК от 26.01.2026 № 5; ПКМ КР от 14.09.2026 № 613","https://docs.eaeunion.org/documents/461/10465/"]];
function markCodeHit(c,qn){
  const r=c.split("-");
  if(r.length===2){const q10=(qn+"0000000000").slice(0,10),lo=(r[0]+"0000000000").slice(0,10),hi=(r[1]+"9999999999").slice(0,10);return (q10>=lo&&q10<=hi)||lo.startsWith(qn)||hi.startsWith(qn);}
  return qn.startsWith(c)||c.startsWith(qn);
}
function findMarking(q){
  const qn=norm(q);if(!qn||qn.length<4)return[];
  return MARK_DB.filter(r=>r[2].some(c=>markCodeHit(c,qn))&&!r[3].some(x=>qn.startsWith(x)));
}
function findTrace(q){
  const qn=norm(q);if(!qn||qn.length<4)return[];
  return TRACE_DB.filter(r=>r[1].some(c=>markCodeHit(c,qn)));
}

function findVET(q){
  const qn=norm(q);if(!qn||qn.length<2)return[];
  return VET_DB.filter(e=>e.codes.some(c=>{const cn=norm(c);return cn.startsWith(qn)||qn.startsWith(cn)}));
}

function findPHYTO(q){
  const qn=norm(q);if(!qn||qn.length<2)return[];
  return PHYTO_DB.filter(e=>e.codes.some(c=>{const cn=norm(c);return cn.startsWith(qn)||qn.startsWith(cn)}));
}

function findSAN(q){
  const qn=norm(q);if(!qn||qn.length<2)return{sections:[],reg:[],sub:[]};
  let reg=SAN_REG_DB.filter(e=>e.codes.some(c=>{const cn=norm(c);return cn.startsWith(qn)||qn.startsWith(cn)}));
  // Некоторые записи (напр. родовая позиция 2915 и конкретные подсубпозиции её солей/эфиров,
  // исключённые из-под регистрации примечанием к Разделу II) одновременно матчатся на один и тот же
  // запрос. Чтобы карточки не противоречили друг другу, более специфичное (длинное) совпадение
  // подавляет более широкое родовое — но только когда код записи сам является префиксом запроса
  // (т.е. запрос достаточно детален, чтобы этот код к нему реально применялся); записи, чей код лишь
  // ЭТИМ запросом охватывается сверху (запрос короче/родовее самого кода), в подавлении не участвуют,
  // иначе запрос по голой позиции 2915 терял бы карточку "Подлежит регистрации".
  const ancestorLen=e=>Math.max(0,...e.codes.map(c=>norm(c)).filter(cn=>qn.startsWith(cn)).map(cn=>cn.length));
  const maxLen=Math.max(0,...reg.map(ancestorLen));
  if(maxLen>0) reg=reg.filter(e=>ancestorLen(e)===maxLen);
  const sub=SAN_SUB_DB.filter(e=>e.codes.some(c=>{const cn=norm(c);return cn.startsWith(qn)||qn.startsWith(cn)}));
  const ch=qn.slice(0,2);
  const sections=SAN_SECTIONS.filter(s=>s.groups.includes(ch));
  return{sections,reg,sub};
}

// --- Мост к устаревшей номенклатуре ------------------------------------
// Часть перечней в этом файле — дословная транскрипция правовых актов
// (НКС — Постановление КМ КР №63 от 10.02.2023; приложения к соглашениям
// ЕАЭС-ОАЭ и ЕАЭС-Сербия), а номенклатура ТН ВЭД с даты этих актов менялась:
// подсубпозиции переномеровывались (2845 90 900 0 → 2845 90 800 0) и
// расщеплялись (HS2022 разбил 8701 20 на 8701 21…8701 29). Переписывать коды
// «на актуальные» нельзя — это исказило бы текст акта, а официальной таблицы
// соответствий в файле нет. Поэтому код акта, которому в действующем ЕТТ не
// соответствует ни одна строка, помечается как устаревший и дополнительно
// сопоставляется по самому глубокому уровню номенклатуры, который в ЕТТ ещё
// существует (10→8→6→4 знака). Совпадение по такому коду всегда показывается
// с явным предупреждением — оно означает «проверьте применимость», а не
// «применяется».
//
// Направление риска у трёх перечней разное, поэтому и формулировки разные:
// пропуск в НКС (экспортный контроль) и в изъятиях ЕАЭС-Сербия опаснее
// ложного срабатывания, а вот у ставок ЕАЭС-ОАЭ наоборот — лишняя
// преференция создаёт риск для декларанта, поэтому там предупреждение
// сформулировано жёстче.
let ETT_PREFIX_SET=null;
function ettPrefixSet(){
  if(ETT_PREFIX_SET)return ETT_PREFIX_SET;
  ETT_PREFIX_SET=new Set();
  for(const r of ETT_DB){
    const c=String(r[0]).replace(/\D/g,'');
    for(const L of [4,6,8,10]) if(c.length>=L) ETT_PREFIX_SET.add(c.slice(0,L));
  }
  return ETT_PREFIX_SET;
}
// null — код актуален (или короче 10 знаков, т.е. и так обобщённый);
// иначе — самый длинный сохранившийся префикс.
function legacyPrefix(code){
  const cn=String(code).replace(/\D/g,'');
  if(cn.length<10)return null;
  const pref=ettPrefixSet();
  if(pref.has(cn))return null;
  for(const L of [8,6,4]){const p=cn.slice(0,L);if(pref.has(p))return p}
  return null;
}
// Ключ — код ровно в том виде, в каком он лежит в базе, а значение содержит
// саму строку. Так горячий путь (findNKS перебирает весь НКС на каждый запрос)
// обходится одним Map.get без регулярки на каждый код, а откат по устаревшим
// кодам в findETTUAE/findETTRS перебирает только сами устаревшие строки
// (десятки), а не всю базу (тысячи).
const LEGACY_MAPS=new Map();
function legacyMapFor(db,codeOf){
  if(LEGACY_MAPS.has(db))return LEGACY_MAPS.get(db);
  const m=new Map();
  for(const row of db){
    const raw=codeOf(row);
    const p=legacyPrefix(raw);
    if(p)m.set(raw,{at:p,row});
  }
  LEGACY_MAPS.set(db,m);
  return m;
}
// Совпадение либо «запрос глубже кода акта», либо «запрос короче и является
// его началом» — та же двусторонняя логика, что и у остальных findX().
function legacyAppliesTo(at,qn){return qn.startsWith(at)||at.startsWith(qn)}

