const TNVED_BASIS={split:'подсубпозиция разделена',merge:'коды объединены',renumber:'код перенумерован',hs:'изменение внесено ГС-2022',new:'код введён позже опубликованной редакции ЕТТ',gone:'кода нет в действующем ЕТТ',typo:'вероятна ошибка переноса кода'};
// Одна формулировка для всех карточек, где сработал откат по устаревшему коду.
function legacyNote(code,at,tail){
  const m=TNVED_MAP[code];
  if(m&&(m.b==='gone'||m.b==='typo')){
    // Это коды не из акта, а из собственной базы ЕТТ: их нет в официальном ЕТТ,
    // поэтому ставку по ним нельзя показывать как действующую.
    const list=m.t.map(x=>'<strong>'+esc(fmtCode(x))+'</strong>').join(', ');
    return `<div style="color:var(--red)"><strong>⚠ Кода нет в действующем ЕТТ ЕАЭС:</strong> ${esc(fmtCode(code))} не значится в официальной публикации ЕЭК (${esc(TNVED_BASIS[m.b])}). ${esc(m.n.charAt(0).toUpperCase()+m.n.slice(1))}. Действующие коды: ${list}. Ставку ниже нельзя считать действующей для этого кода.</div><div class="more-hint">Сверено ${esc(m.d)} с источником: ${esc(m.s)}.${tail?' '+esc(tail):''}</div>`;
  }
  if(m&&m.b==='new'){
    // Обратный случай: код не устарел, а наоборот новее опубликованной главы ЕТТ.
    return `<div><strong>ℹ Код новее опубликованной редакции ЕТТ:</strong> ${esc(fmtCode(code))} ${esc(m.n)}. Предшествующая позиция: <strong>${esc(fmtCode(m.t[0]))}</strong>.</div><div class="more-hint">Проверено ${esc(m.d)} по ${esc(m.s)}.${tail?' '+esc(tail):''}</div>`;
  }
  if(m){
    const list=m.t.map(x=>'<strong>'+esc(fmtCode(x))+'</strong>').join(', ');
    return `<div><strong>⚠ Код акта устарел:</strong> ${esc(fmtCode(code))} в действующей ТН ВЭД отсутствует (${esc(TNVED_BASIS[m.b]||m.b)}). Действующие коды: ${list}.${m.n?' '+esc(m.n)+'.':''}</div><div class="more-hint">Основание сопоставления: ${esc(m.s)}. Сверено ${esc(m.d)}. Сводной таблицы соответствия редакций ТН ВЭД ЕЭК не публикует, поэтому применимость к конкретному товару проверяйте по описанию позиции.${tail?' '+esc(tail):''}</div>`;
  }
  return `<div><strong>⚠ Код акта устарел:</strong> ${esc(fmtCode(code))} в действующей ТН ВЭД отсутствует, действующий аналог не установлен; совпадение с запросом найдено только на уровне ${at?at.length:0} знаков${at?' ('+esc(fmtCode(at))+')':''}.${tail?' '+esc(tail):''}</div>`;
}

const NKS_ICONS=['\u{1F9EC}','\u2697\uFE0F','\u2622\uFE0F','\u269B\uFE0F','\u{1F680}','\u{1F527}','\u{1F527}','\u{1F527}','\u{1F6E1}\uFE0F','\u{1F3AF}'];
// По одной карточке на список НКС. Карточка перечисляет конкретные пункты акта,
// по которым код попал в список, — это проверяемое утверждение, а не рубрика,
// выведенная эвристикой. Коды из NKS_UNVER (нет ни в одной редакции акта)
// собираются в отдельную карточку с явной оговоркой. Актуальное совпадение
// всегда вытесняет совпадение по устаревшему коду.
function findNKS(q){
  const qn=norm(q);if(!qn||qn.length<4)return[];
  const legacy=legacyMapFor(NKS,c=>c);
  const byList=new Map();
  for(const c of NKS){
    let at=null,isLegacy=false;
    if(!(c.startsWith(qn)||qn.startsWith(c.slice(0,Math.min(qn.length,10))))){
      const L=legacy.get(c);
      if(!L||!legacyAppliesTo(L.at,qn))continue;
      at=L.at;isLegacy=true;
    }
    const refs=NKS_MAP[c];
    // Код без подтверждения в акте, да ещё и подобранный откатом по устаревшей
    // номенклатуре, — двойное предположение; такую карточку не показываем.
    if(!refs&&isLegacy)continue;
    const keys=refs&&refs.length?refs.map(i=>'L'+NKS_ITEMS[i][0]):['U'];
    keys.forEach((key,n)=>{
      let e=byList.get(key);
      if(!e){e={key,list:key==='U'?-1:NKS_ITEMS[refs[n]][0],unver:key==='U',items:[],codes:[],legacy:true,legacyAt:null};byList.set(key,e)}
      if(!isLegacy)e.legacy=false;else if(!e.legacyAt)e.legacyAt=at;
      if(!e.codes.includes(c))e.codes.push(c);
      if(refs&&!e.items.includes(refs[n]))e.items.push(refs[n]);
    });
  }
  return [...byList.values()].sort((a,b)=>a.list-b.list);
}

// Одному коду может отвечать несколько пунктов статьи 336 (например 2204 — и
// «Вина», и «Вина игристые»): акт различает их по виду товара, а не по коду,
// поэтому возвращаются все совпадения, а выбор остаётся за декларантом.
function findExcise(q){
  const qn=norm(q).replace(/[^0-9]/g,'');
  if(!qn||qn.length<4)return[];
  const res=[];
  for(const r of EXCISE_DB){
    let hit=false;
    for(const m of r[6]){
      if(Array.isArray(m)){
        const L=Math.min(qn.length,m[0].length,m[1].length);
        if(m[0].slice(0,L)<=qn.slice(0,L)&&qn.slice(0,L)<=m[1].slice(0,L)){hit=true;break}
      } else if(m.startsWith(qn)||qn.startsWith(m)){hit=true;break}
    }
    if(hit&&r[7].some(e=>qn.startsWith(e)))hit=false;
    if(hit)res.push(r);
  }
  return res;
}
function findNBNDS(q){
  const qn=norm(q).replace(/[^0-9]/g,'');
  if(!qn||qn.length<4)return[];
  const res=[];
  for(const r of NBNDS_DB){
    const c=r[1];
    if(c.startsWith(qn)||qn.startsWith(c))res.push(r);
  }
  return res;
}
function findKef1606(q){
  const qn=norm(q);if(!qn||qn.length<4)return null;
  for(const c in KEF1606_MAP){
    if(c.startsWith(qn)||qn.startsWith(c)){ return {code:c, group:KEF1606_MAP[c][0], coef:KEF1606_MAP[c][1]}; }
  }
  return null;
}
// Мера с машинной датой окончания (rec[6], последний день включительно) после неё не действующая:
// предупреждение калькулятора и сводка партии говорят «действуют», карточка помечает истёкшие.
function adActive(rec,today){
  const u=rec[6];
  return !u||(today||new Date(Date.now()+6*3600e3).toISOString().slice(0,10))<=u;
}
function findAntidump(q){
  const qn=norm(q);if(!qn||qn.length<4)return[];
  const res=[];
  for(const rec of ANTIDUMP_DB){
    const codes=rec[0];
    if(codes.some(c=>c.startsWith(qn)||qn.startsWith(c))) res.push(rec);
  }
  return res;
}
function findEECDec(q){
  const qn=norm(q);if(!qn||qn.length<4)return[];
  const res=[];
  for(const r of EEC_DECISIONS){
    const codes=r[1];
    // Только когда запрос ТОЧНЕЕ/РАВЕН коду решения (не наоборот) — решения нередко привязаны
    // не к полному коду, а к целой товарной позиции (напр. «1901», «2009»), и без этого условия
    // решение про один конкретный товар всплывало бы у всех кодов внутри такой позиции.
    if(codes.some(c=>qn.startsWith(c))) res.push(r);
  }
  return res;
}
function findSpecies(q){
  const qq=(q||'').trim().toLowerCase();
  if(qq.length<2)return[];
  const words=qq.split(/\s+/).filter(w=>w.length>0);
  const res=[];
  for(const r of SPECIES_DB){
    const [ru,lat,status,kind]=r;
    const combined=(ru+' '+lat).toLowerCase();
    if(words.every(w=>combined.includes(w))){
      res.push(r);
      if(res.length>=200)break;
    }
  }
  return res;
}
