const STOPWORDS_RU=new Set(['для','из','на','к','ко','и','с','со','в','во','от','по','за','без','над','под','при','до','у','о','об','а','но','или','не','ли','же','то','это','эта','этот','эти','как','что','чем','также','либо','через','между']);
function hasWordAt(name,word){
  // проверяет совпадение word в name только на границе слова (не внутри случайного другого слова)
  // допускает продолжение справа (чтобы "рюкзак" находил "рюкзаки"), но слева обязательна граница
  let idx=0;
  while(true){
    const pos=name.indexOf(word,idx);
    if(pos===-1)return false;
    const prev=pos===0?'':name[pos-1];
    if(!prev||!/[а-яёa-z0-9]/i.test(prev))return true;
    idx=pos+1;
  }
}
function findByName(q){
  const qq=(q||'').trim().toLowerCase();
  if(qq.length<3)return[];
  let words=qq.split(/\s+/).filter(w=>w.length>0);
  const filtered=words.filter(w=>!STOPWORDS_RU.has(w));
  if(filtered.length>0)words=filtered; // отбрасываем предлоги/союзы, если после фильтрации что-то остаётся
  // для каждого слова запроса — само слово ИЛИ (все слова одной из синоним-фраз)
  const wordVariants=words.map(w=>{
    const phrases=(SEARCH_SYNONYMS[w]||[]).map(p=>p.split(/\s+/));
    return {self:w,phrases};
  });
  const wordMatches=(name,{self,phrases})=>
    hasWordAt(name,self)||phrases.some(ph=>ph.every(pw=>hasWordAt(name,pw)));
  // слово считается "значимым", если оно совпадает хоть с одной записью базы ГДЕ УГОДНО.
  // слова, которые не встречаются в базе нигде (цвета, бренды, разговорные прилагательные
  // типа "теплый", "хороший" и т.п.) не должны обнулять весь результат — они игнорируются
  // как фильтр, но участвуют в подсветке совпадений.
  const anyMatch=new Array(wordVariants.length).fill(false);
  for(const r of ETT_DB){
    const name=(r[1]||'').toLowerCase();
    let allFound=true;
    for(let i=0;i<wordVariants.length;i++){
      if(!anyMatch[i]){
        if(wordMatches(name,wordVariants[i]))anyMatch[i]=true;
        else allFound=false;
      }
    }
    if(allFound)break; // все слова уже подтверждены значимыми — дальше искать нечего
  }
  // Второй источник "значимости" слова — разговорные названия товаров из решений ЕЭК
  // (EEC_DECISIONS, см. findEECDec выше): многие из них ("Гарнитура «BLUETOOTH»", "Мясорубки
  // бытовые и промышленные") вообще не встречаются в сухом тексте ЕТТ, поэтому без этой
  // добавки слово так и осталось бы "незначимым" и не задействовало бы этот источник.
  if(!anyMatch.every(Boolean)){
    for(const d of EEC_DECISIONS){
      const name=(d[4]||'').toLowerCase();
      let allFound=true;
      for(let i=0;i<wordVariants.length;i++){
        if(!anyMatch[i]){
          if(wordMatches(name,wordVariants[i]))anyMatch[i]=true;
          else allFound=false;
        }
      }
      if(allFound)break;
    }
  }
  const activeIdx=wordVariants.map((_,i)=>i).filter(i=>anyMatch[i]);
  // если вообще ни одно слово не встречается в базе (например, опечатка) — не молчим,
  // а используем все слова как есть, чтобы результат остался пустым и это было видно
  const useIdx=activeIdx.length>0?activeIdx:wordVariants.map((_,i)=>i);
  const res=[];
  const seenCodes=new Set();
  for(const r of ETT_DB){
    const name=(r[1]||'').toLowerCase();
    const ok=useIdx.every(i=>wordMatches(name,wordVariants[i]));
    if(ok){
      res.push(r);
      seenCodes.add(r[0]);
      if(res.length>=150)break;
    }
  }
  // Названия из решений ЕЭК сами по себе не несут ставку/единицу измерения — при совпадении
  // подставляем настоящую строку (строки) ЕТТ по коду решения. Сначала точное совпадение кода;
  // если решение привязано не к конкретному тарифному коду, а к целой товарной позиции без
  // собственной строки в ЕТТ (напр. "7308" у металлочерепицы — сама позиция строки ставки не
  // имеет, только вложенные в неё подсубпозиции), берём несколько (не все — чтобы не подменить
  // собой полный список из "Классификатора ТН ВЭД") её кодов, начинающихся с этого префикса.
  if(res.length<150){
    outerDec:
    for(const d of EEC_DECISIONS){
      const name=(d[4]||'').toLowerCase();
      const ok=useIdx.every(i=>wordMatches(name,wordVariants[i]));
      if(!ok)continue;
      for(const c of d[1]){
        if(seenCodes.has(c))continue;
        const exact=ETT_DB.find(r=>r[0]===c);
        const matches=exact?[exact]:ETT_DB.filter(r=>r[0].startsWith(c)).slice(0,3);
        for(const r of matches){
          if(seenCodes.has(r[0]))continue;
          seenCodes.add(r[0]);
          res.push(r);
          if(res.length>=150)break outerDec;
        }
      }
    }
  }
  return res;
}
function findLS(q){
  const qn=norm(q);if(!qn||qn.length<4)return[];
  const res=[];
  for(const [code,names] of Object.entries(LS_CODES)){
    const cn=norm(code);
    if(cn.startsWith(qn)||qn.startsWith(cn.slice(0,Math.min(qn.length,10)))){
      res.push({code,names});
    }
  }
  return res;
}
// Карточки выдачи по запросу — код или наименование. Возвращает разметку и признак
// cards: у выдачи карточками браузер сворачивает их и строит сводку, у списка
// кандидатов по наименованию — нет. Вызывается браузером через /api/engine и помощником.
function renderHtml(q,dateIso){dateIso=/^\d{4}-\d\d-\d\d$/.test(dateIso||'')?dateIso:'';
  const qt=String(q||'').trim();
  if(!qt)return {html:'',cards:false};
  const bans=findBan(qt),nksList=findNKS(qt),lsList=findLS(qt),sertList=findSert(qt),medList=findMed(qt),matList=findMat(qt),art297List=findArt297(qt),art300List=findArt300(qt),art301Hit=findArt301(qt),art297PerechenList=findArt297Perechen(qt),art298List=findArt298(qt),art299List=findArt299(qt),app6VetList=findApp6Vet(qt),art297P20List=findArt297P20(qt),art297P26List=findArt297P26(qt),art297P30List=findArt297P30(qt),eecList=findEEC30(qt),wasteList=findEECWaste(qt),ettList=findETT(qt),uaeList=findETTUAE(qt),mnList=findETTMN(qt),rsList=findETTRS(qt),iranList=findETTIran(qt),vnList=findETTVN(qt),nbndsList=findNBNDS(qt),exciseList=findExcise(qt),kefHit=findKef1606(qt),adList=findAntidump(qt),triggerList=findTrigger(qt),quotaList=findQuota(qt),eecDecList=findEECDec(qt),vetList=findVET(qt),vetTempList=findVetTemp(qt),markList=findMarking(qt),traceList=findTrace(qt),phytoList=findPHYTO(qt),sanRes=findSAN(qt),treaList=findTREAEU(qt),troisList=findTROIS(qt),prefList=findPref(qt),uniList=findUniMeasure(qt,dateIso);
  if(!bans.length&&!nksList.length&&!lsList.length&&!sertList.length&&!medList.length&&!matList.length&&!art297List.length&&!art300List.length&&!art301Hit&&!art297PerechenList.length&&!art298List.length&&!art299List.length&&!app6VetList.length&&!art297P20List.length&&!art297P26List.length&&!art297P30List.length&&!eecList.length&&!wasteList.length&&!ettList.length&&!uaeList.length&&!mnList.length&&!rsList.length&&!iranList.length&&!vnList.length&&!nbndsList.length&&!exciseList.length&&!kefHit&&!adList.length&&!triggerList.length&&!quotaList.length&&!eecDecList.length&&!vetList.length&&!vetTempList.length&&!markList.length&&!traceList.length&&!phytoList.length&&!sanRes.sections.length&&!sanRes.reg.length&&!sanRes.sub.length&&!treaList.length&&!troisList.length&&!prefList.length&&!uniList.length){
    // Запрос из одних цифр — это код, и по наименованию он не ищется: «9999 99 999 9»
    // находил серебро и платину 999 пробы. Ответ — «кода нет» и ближайшие действующие коды.
    const qDigits=qt.replace(/\D/g,'');
    if(/^[\d\s]+$/.test(qt)&&qDigits.length>=4){
      const hint=specNotFoundHint(qDigits);
      return {cards:false,html:`<div class="nf"><div class="big">🔍</div>Кода <strong>${esc(fmtCode(qDigits))}</strong> нет в действующем ЕТТ ЕАЭС<br><span style="color:var(--hint);margin-top:6px;display:block">${esc(hint.charAt(0).toUpperCase()+hint.slice(1))}. Проверьте цифры или введите название товара.</span></div>`};
    }
    // Запрос не похож ни на один известный код — пробуем как название товара,
    // чтобы поиск по коду и по наименованию работали из одного поля.
    const nameList=findByName(qt);
    // Товарный знак ищется по названию, а не по коду: пользователь знает бренд.
    // Карточка реестра идёт первой — запрос «VENTANA» относится именно к ней,
    // а совпадения по наименованию товара в ЕТТ здесь побочные.
    const troisNames=findTROISByName(qt);
    // Запрос вида «Бангладеш» или «Вьетнам» — это вопрос о преференции,
    // а не о товаре: карточка страны идёт первой, совпадения по знаку и по
    // наименованию остаются под ней.
    const prefCountries=findPrefByCountry(qt);
    const cisHit=cisCountry(qt);
    if(prefCountries.length||cisHit){
      return {cards:false,html:(cisHit?cisCountryHtml(cisHit):'')+(prefCountries.length?prefCountryHtml(qt,prefCountries):'')
        +(troisNames.length?troisNameHtml(qt,troisNames):'')
        +(nameList.length?nameMatchesHtml(qt,nameList):'')};
    }
    if(troisNames.length){
      return {cards:false,html:troisNameHtml(qt,troisNames)+(nameList.length?nameMatchesHtml(qt,nameList):'')};
    }
    if(nameList.length){
      // Не сворачиваем: единственная карточка тут — это и есть кликабельный
      // список кандидатов (onclick=goToCode), а не «детали», которые нужно
      // прятать — сворачивание заставляло бы делать лишний клик перед тем,
      // как вообще увидеть список.
      return {cards:false,html:nameMatchesHtml(qt,nameList)};
    }
    return {cards:false,html:`<div class="nf"><div class="big">🔍</div>«<strong>${esc(qt)}</strong>» не найдено ни по коду, ни по наименованию<br><span style="color:var(--hint);margin-top:6px;display:block">Такого кода нет в действующем ЕТТ, а по названию совпадений нет. Проверьте цифры или введите название товара — например, «лом металлов».</span></div>`};
  }
  let html='';

  // Десять цифр, которых нет в ЕТТ: меры ниже найдены по началу кода, и об этом надо сказать первым.
  {const qd=qt.replace(/\D/g,'');
    if(/^[\d\s]+$/.test(qt)&&qd.length===10&&!ETT_DB.some(r=>r[0]===qd)){
      const hint=specNotFoundHint(qd);
      html+=`<div class="card c-ok" data-nocode="1"><div class="rh"><div class="ico">❓</div><div><div class="rc">${esc(fmtCode(qd))}</div></div></div><div class="rn">Такого кода нет в действующем ЕТТ ЕАЭС</div><div class="tags"><span class="tag t-eec-dual">❓ Кода нет в ЕТТ</span></div><div class="det"><div>${esc(hint.charAt(0).toUpperCase()+hint.slice(1))}. Карточки ниже найдены по совпадению начала кода с позициями перечней и относятся к товарной позиции, а не к этому коду.</div></div></div>`;
    }}
  // Ставка ввозной таможенной пошлины (ЕТТ ЕАЭС)
  if(ettList.length>0){
    if(ettList.length===1){
      const [ec,en,eu,er]=ettList[0];
      html+=`<div class="card c-ett" data-dir="im" data-kind="tariff"><div class="rh"><div class="ico">💰</div><div><div class="rc">${esc(fmtCode(ec))}</div></div></div><div class="rn">${ettNameRowHtml(ec,en)}</div><div class="tags"><span class="tag t-ett">💰 Ставка ввозной пошлины</span></div><div class="rn" style="margin-top:2px">${ettNameHtml(ec,en)}</div><div class="ett-rate">${esc(fmtRate(er))}</div><div class="det">${quickActionsHtml(ec)}<div><strong>Доп. ед. изм.:</strong> ${esc(eu||'не указана')}</div><div><strong>Источник:</strong> ЕТТ ЕАЭС, база пользователя 2026</div>${TNVED_MAP[ec]?legacyNote(ec,null,''):''}${auditNote('ett')}<div style="margin-top:8px"><span class="notes-ico" style="margin-left:0;opacity:.85" onclick="openNotesForCode('${ec}')">📖 Пояснения к группе ${esc(ec.slice(0,2))} ТН ВЭД</span></div></div></div>`;
    } else {
      const shown=ettList.slice(0,30);
      let rowsHtml='';
      for(const [ec,en,eu,er] of shown){
        const gone=TNVED_MAP[ec]&&(TNVED_MAP[ec].b==='gone'||TNVED_MAP[ec].b==='typo');
        rowsHtml+=`<div class="ett-row" style="cursor:pointer${gone?';opacity:.75':''}" onclick="goToCode('${ec}')"><div class="ec">${esc(fmtCode(ec))}${gone?' <span title="Кода нет в действующем ЕТТ ЕАЭС — откройте позицию, чтобы увидеть действующие коды" style="color:var(--red)">⚠</span>':''}</div><div class="en">${ettNameRowHtml(ec,en)}</div><div class="er">${esc(fmtRate(er))}</div>${notesIconHtml(ec)}</div>`;
      }
      const moreNote=ettList.length>shown.length?`<div class="ett-more">Показаны первые ${shown.length} из ${ettList.length} позиций — введите больше цифр кода, чтобы уточнить</div>`:'';
      // При больше чем 2 позициях таблица кодов/ставок на всю ширину карточки
      // читается плохо, если сжать её в узкую колонку сетки — растягиваем
      // карточку на всю ширину строки (grid-column:1/-1). При 1-2 позициях
      // строк мало, обычная колонка сетки смотрится нормально — не трогаем.
      const wideAttr=ettList.length>2?' style="grid-column:1/-1"':'';
      html+=`<div class="card c-ett" data-dir="im" data-kind="tariff"${wideAttr}><div class="rh"><div class="ico">💰</div><div><div class="rc">${esc(qt)}…</div></div></div><div class="rn">Ставки ввозной пошлины ЕТТ — найдено ${ettList.length} позиций</div><div class="tags"><span class="tag t-ett">💰 ЕТТ ЕАЭС</span></div><div class="ett-list">${rowsHtml}</div>${moreNote}</div>`;
    }
  }
  // Преференциальная ставка по Соглашению ЕАЭС-ОАЭ (только для товаров, происходящих из ОАЭ)
  if(uaeList.length>0){
    const yearsHdr=['2026','2027','2028','2029','2030','2031','2032','2033+'];
    // График расписан по годам вперёд до 2033+, но на практике интересен почти
    // всегда только текущий год — остальные загромождали карточку. Год берём
    // по реальной дате зрителя, а не хардкодим: index 0..6 = 2026..2032,
    // index 7 ("2033+") — любой год 2033 и позже.
    const nowY=new Date().getFullYear();
    const curIdx=Math.min(Math.max(nowY-2026,0),yearsHdr.length-1);
    const curYearLbl=yearsHdr[curIdx];
    let rows='';
    for(const uRow of uaeList.slice(0,20)){
      const [ec,en,rates]=uRow;
      const allEtt=rates.every(r=>r==='ставка ЕТТ');
      const curRate=rates[curIdx];
      const body=allEtt
        ? `<div class="uu" style="margin-top:6px;color:var(--red)">⚠️ Льготного графика по этому коду нет — во все годы (2026–2033+) применяется обычная ставка ЕТТ, преференция ЕАЭС-ОАЭ фактически не действует</div>`
        : `<div class="uu" style="margin-top:6px"><span style="font-size:11px;color:var(--muted)">Ставка на ${curYearLbl} год:</span> <span style="font-weight:600">${esc(curRate)}${curRate!=='ставка ЕТТ'&&curRate!=='0'?'%':''}</span></div>`
          +`<details style="margin-top:4px"><summary style="cursor:pointer;font-size:11px;color:var(--indigo)">График по всем годам (2026–2033+)</summary>`
          +`<div style="display:flex;flex-wrap:wrap;gap:10px;margin-top:6px">${rates.map((r,i)=>`<div style="min-width:64px"><div style="font-size:10px;color:var(--muted)">${yearsHdr[i]}</div><div style="font-weight:600">${esc(r)}${r!=='ставка ЕТТ'&&r!=='0'?'%':''}</div></div>`).join('')}</div></details>`;
      const uLegacy=(uRow.legacy||TNVED_MAP[ec])?`<div class="uu" style="margin-top:6px;color:var(--red)">${legacyNote(ec,uRow.legacyAt,'Ставка приведена справочно: применять преференцию можно только сверив позицию с текстом Соглашения.')}</div>`:'';
      rows+=`<div class="usir-row"><div class="un">${esc(fmtCode(ec))} — ${esc(en)}</div>${body}${uLegacy}</div>`;
    }
    const moreNote=uaeList.length>20?`<div class="ett-more">Показаны первые 20 из ${uaeList.length} позиций — введите больше цифр кода, чтобы уточнить</div>`:'';
    html+=`<div class="card c-ett" data-dir="im" data-kind="tariff" data-cty="оаэ эмираты"><div class="rh"><div class="ico">🇦🇪</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">Код входит в перечень исключений к Соглашению об экономическом партнёрстве ЕАЭС-ОАЭ от 27.06.2025 — для товаров, происходящих из ОАЭ, действует не общая преференция 0%, а собственный график ставок по годам</div><div class="tags"><span class="tag t-ett">🇦🇪 Ставка ЕАЭС-ОАЭ</span></div><div class="usir-list">${rows}</div>${moreNote}<div class="det"><strong>Важно:</strong> применяется только к товарам, ПРОИСХОДЯЩИМ из ОАЭ (нужен сертификат происхождения по Соглашению), По кодам вне перечня действует ставка 0%, по кодам перечня — ставка графика на соответствующий год; если пошлина по обычной ставке ЕТТ получается ниже, применяется ставка ЕТТ (п.2 Решения №113). Для золотых/серебряных/платиновых слитков отмеченных «ставка ЕТТ» в графике — при ввозе для последующей переработки с подтверждающим документом уполномоченного органа страны-члена возможна ставка 0% вне зависимости от стоимости (п.3 Решения №113). Источник: ${docLink('Решение Коллегии ЕЭК №113 от 25.08.2026','https://docs.eaeunion.org/documents/463/10896/')}. <strong>Дата вступления решения в силу — 06.10.2026</strong> (опубликовано 28.08.2026; по пункту 4 решение вступает в силу с даты вступления в силу Соглашения, но не ранее 30 календарных дней с даты опубликования). До этой даты приведённый график ставок не применяется.${auditNote('uae')}</div></div>`;
  }

  // Преференциальная ставка по Временному торговому соглашению ЕАЭС-Монголия (только для товаров, происходящих из Монголии)
  if(mnList.length>0){
    let rows='';
    for(const [mc,mn,mr] of mnList.slice(0,20)){
      const rateHtml=mr==='0'?'0% (пошлина не взимается)':esc(mr);
      rows+=`<div class="usir-row"><div class="un">${esc(fmtCode(mc))} — ${esc(mn)}</div><div class="uu">${rateHtml}</div></div>`;
    }
    const moreNote=mnList.length>20?`<div class="ett-more">Показаны первые 20 из ${mnList.length} позиций — введите больше цифр кода, чтобы уточнить</div>`:'';
    html+=`<div class="card c-ett" data-dir="im" data-kind="tariff" data-cty="монголия"><div class="rh"><div class="ico">🇲🇳</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">Код входит в перечень товаров, происходящих из Монголии, к которым применяется преференциальная ставка ввозной пошлины</div><div class="tags"><span class="tag t-ett">🇲🇳 Ставка ЕАЭС-Монголия</span></div><div class="usir-list">${rows}</div>${moreNote}<div class="det"><strong>Важно:</strong> применяется только к товарам, ПРОИСХОДЯЩИМ из Монголии (нужен сертификат происхождения по Соглашению), Если пошлина по обычной ставке ЕТТ получается ниже, применяется ставка ЕТТ (п.2 Решения №74); по кодам вне перечня Временное соглашение ставку ЕТТ не меняет. Источник: ${docLink('Решение Коллегии ЕЭК №74 от 16.06.2026','https://docs.eaeunion.org/documents/463/10743/')} — перечень товаров с преференциальными ставками по Временному торговому соглашению ЕАЭС-Монголия от 27.06.2025. Сводная публикация ЕЭК: ${docLink('Перечень_Монголия на 22-07-2026 (PDF)','https://eec.eaeunion.org/comission/department/catr/ttr/Preferences/Mongolia/%D0%9F%D0%B5%D1%80%D0%B5%D1%87%D0%B5%D0%BD%D1%8C_%D0%9C%D0%BE%D0%BD%D0%B3%D0%BE%D0%BB%D0%B8%D1%8F%20%D0%BD%D0%B0%2022-07-2026.pdf')}.${auditNote('mn')}</div></div>`;
  }

  // Пониженная ставка ЕТТ по Соглашению о свободной торговле ЕАЭС-Иран от 25.12.2023
  // (перечень утверждён Решением Коллегии ЕЭК №1 от 14.01.2025, в ред. Решения №43 от 07.04.2026;
  // содержит только коды с фактически иной ставкой — по всем прочим кодам перечень оставляет обычную ставку ЕТТ)
  if(iranList.length>0){
    let rows='';
    for(const [ic,iname,irate,iiz,,irfn] of iranList.slice(0,20)){
      rows+=`<div class="usir-row"><div class="un">${iiz?'из ':''}${esc(fmtCode(ic))} — ${esc(iname)}</div><div class="uu">${esc(irate)}${irfn==='**'?' — в пределах тарифной квоты при лицензии 0%':''}</div></div>`;
    }
    const moreNote=iranList.length>20?`<div class="ett-more">Показаны первые 20 из ${iranList.length} позиций — введите больше цифр кода, чтобы уточнить</div>`:'';
    html+=`<div class="card c-ett" data-dir="im" data-kind="tariff" data-cty="иран"><div class="rh"><div class="ico">🇮🇷</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">Код входит в перечень к Соглашению ЕАЭС-Иран — для товаров, происходящих из Ирана, действует не общая ставка 0%, а ставка перечня</div><div class="tags"><span class="tag t-ett">🇮🇷 Ставка ЕАЭС-Иран</span></div><div class="usir-list">${rows}</div>${moreNote}<div class="det"><strong>Важно:</strong> применяется только к товарам, ПРОИСХОДЯЩИМ из Ирана (нужен сертификат происхождения по Соглашению о свободной торговле ЕАЭС-Иран от 25.12.2023), По кодам вне перечня действует ставка 0% (абз.1 п.2 Решения №1). По строкам перечня — указанная ставка, а «ставка ЕТТ» означает, что льготы нет; если пошлина по обычной ставке ЕТТ получается ниже ставки перечня, применяется ЕТТ (абз.2 п.2). Строки со сноской ** — товары тарифных квот: в пределах квоты при лицензии ставка 0%. Источник: ${docLink('Решение Коллегии ЕЭК №1 от 14.01.2025 (в ред. Решения №43 от 07.04.2026) — перечень товаров со ставками по Соглашению ЕАЭС-Иран','https://eec.eaeunion.org/comission/department/catr/ttr/Preferences/Iran/%D0%BF%D0%B5%D1%80%D0%B5%D1%87%D0%B5%D0%BD%D1%8C%20%D0%98%D0%A0%D0%90%D0%9D%20%D0%BD%D0%B0%2001-07-2026.pdf')}.${auditNote('ir')}</div></div>`;
  }

  // Пониженная ставка ЕТТ по Соглашению о свободной торговле ЕАЭС-Вьетнам от 29.05.2015
  // (перечень утверждён Решением Коллегии ЕЭК №36 от 19.04.2016, в ред. Решения №119 от 29.10.2024;
  // содержит только коды с фактически иной ставкой — по всем прочим кодам перечень оставляет обычную ставку ЕТТ)
  if(vnList.length>0){
    let rows='';
    for(const [vc,vname,vrate,viz] of vnList.slice(0,20)){
      rows+=`<div class="usir-row"><div class="un">${viz?'из ':''}${esc(fmtCode(vc))} — ${esc(vname)}</div><div class="uu">${esc(vrate)}</div></div>`;
    }
    const moreNote=vnList.length>20?`<div class="ett-more">Показаны первые 20 из ${vnList.length} позиций — введите больше цифр кода, чтобы уточнить</div>`:'';
    html+=`<div class="card c-ett" data-dir="im" data-kind="tariff" data-cty="вьетнам"><div class="rh"><div class="ico">🇻🇳</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">Код входит в перечень к Соглашению ЕАЭС-Вьетнам — для товаров, происходящих из Вьетнама, действует не общая ставка 0%, а ставка перечня</div><div class="tags"><span class="tag t-ett">🇻🇳 Ставка ЕАЭС-Вьетнам</span></div><div class="usir-list">${rows}</div>${moreNote}<div class="det"><strong>Важно:</strong> применяется только к товарам, ПРОИСХОДЯЩИМ из Вьетнама (нужен сертификат происхождения по Соглашению о свободной торговле ЕАЭС-Вьетнам от 29.05.2015), По кодам вне перечня действует ставка 0% (п.2 Решения №36), кроме спортивной обуви 6403 91 и 6403 99 при невыполнении условий п.3 и товаров под триггерной защитной мерой. По строкам перечня — указанная ставка, «ставка ЕТТ» означает, что льготы нет; для отдельных товарных позиций (одежда/трикотаж 6103/6104/6110/6203/6204) с 23.05.2026 по 23.11.2026 льгота ВРЕМЕННО не действует (защитная мера, Решение №47 от 20.04.2026, см. карточку триггерной меры). Источник: ${docLink('Решение Коллегии ЕЭК №36 от 19.04.2016 (в ред. Решения №119 от 29.10.2024) — перечень товаров со ставками по Соглашению ЕАЭС-Вьетнам','https://eec.eaeunion.org/comission/department/catr/ttr/Preferences/Vietnam/%D0%BF%D0%B5%D1%80%D0%B5%D1%87%D0%B5%D0%BD%D1%8C%20%D0%92%D1%8C%D0%B5%D1%82%D0%BD%D0%B0%D0%BC%20%D0%BD%D0%B0%2022-01-2026.pdf')}.${auditNote('vn')}</div></div>`;
  }

  // Изъятие из режима свободной торговли ЕАЭС-Сербия (для товаров из Сербии по умолчанию 0%, кроме этого перечня)
  if(rsList.length>0){
    let rows='';
    for(const rRow of rsList.slice(0,20)){
      const [rc,rn,rr,rnote]=rRow;
      const noteHtml=rnote?`<div class="uu" style="margin-top:4px">${esc(rnote)}</div>`:'';
      const rMapped=rRow.mappedFrom?`<div class="uu" style="margin-top:4px">Запрошенный код <strong>${esc(fmtCode(rRow.mappedFrom))}</strong> в действующей редакции перечня заменён на <strong>${esc(fmtCode(rc))}</strong> — строка ниже относится к действующему коду. ${esc(TNVED_MAP[rRow.mappedFrom].n)}. Сверено ${esc(TNVED_MAP[rRow.mappedFrom].d)}.</div>`:'';
      const rLegacy=(rRow.legacy||TNVED_MAP[rc])?`<div class="uu" style="margin-top:4px;color:var(--red)">${legacyNote(rc,rRow.legacyAt,'Изъятие означает, что преференция 0% не действует, поэтому проверьте по тексту перечня, охватывает ли оно ваш код.')}</div>`:'';
      rows+=`<div class="usir-row"><div class="un">${esc(fmtCode(rc))} — ${esc(rn)}</div><div class="uu">${esc(rr)}</div>${rMapped}${noteHtml}${rLegacy}</div>`;
    }
    const moreNote=rsList.length>20?`<div class="ett-more">Показаны первые 20 из ${rsList.length} позиций — введите больше цифр кода, чтобы уточнить</div>`:'';
    html+=`<div class="card c-ett" data-dir="im" data-kind="tariff" data-cty="сербия"><div class="rh"><div class="ico">🇷🇸</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">Код входит в перечень ИЗЪЯТИЙ из режима свободной торговли ЕАЭС-Сербия — для товаров, происходящих из Сербии, по этому коду преференция 0% НЕ действует</div><div class="tags"><span class="tag t-ett">🇷🇸 Изъятие ЕАЭС-Сербия</span></div><div class="usir-list">${rows}</div>${moreNote}<div class="det"><strong>Важно:</strong> для товаров, происходящих из Республики Сербии, по Соглашению о зоне свободной торговли от 25.10.2019 действует общая преференция 0% пошлины — КРОМЕ товаров из этого перечня изъятий, где применяется обычная ставка ЕТТ (у части позиций — с дополнительными оговорками по квоте/сертификату/для бывших в эксплуатации ТС, см. примечание). Источник: перечень, утверждённый Решением Коллегии ЕЭК №122 от 06.10.2020, в редакции решений Коллегии ЕЭК №123 от 21.09.2021 и №81 от 23.09.2025 (сводная публикация ЕЭК от 22.01.2026), с расщеплением кода 5804 21 900 0 по Решению №94 от 14.07.2026.${auditNote('rs')}</div></div>`;
  }

  // Тарифные преференции ЕАЭС развивающимся и наименее развитым странам (ЕСТП)
  if(prefList.length>0){
    const devH=prefList.filter(p=>p.sec===0),ldcH=prefList.filter(p=>p.sec===1);
    // Ставка ЕТТ по этому коду известна только когда запрос попал ровно в одну
    // позицию и ставка адвалорная (число). Комбинированную ставку («10%, но не
    // менее 0,5 евро за 1 кг») нельзя умножить на 0,75 по одной цифре, поэтому
    // для неё показываем правило, а не результат.
    const ettR=(ettList.length===1&&typeof ettList[0][3]==='number')?ettList[0][3]:null;
    const pct=v=>String(Math.round(v*1000)/1000).replace('.',',');
    const live=h=>h.length&&h.some(p=>!p.ex.length);
    const devLive=live(devH),ldcLive=live(ldcH);
    const head=[];
    if(devLive)head.push((ettR===null?'75% от ЕТТ':(ettR===0?'75% от ЕТТ (и так 0%)':pct(ettR*0.75)+'% вместо '+pct(ettR)+'%'))+' — развивающиеся');
    if(ldcLive)head.push('0% — наименее развитые');
    const headTxt=head.length?head.join(' · '):'не предоставляется';
    const block=(hits,title,rateTxt)=>{
      if(!hits.length)return `<div class="usir-row"><div class="un">${esc(title)}</div><div class="uu">Код в перечень не входит — преференция не предоставляется</div></div>`;
      let rows='';
      for(const p of hits){
        const pos=prefCodeList(p.incAll,6);
        let verdict;
        if(p.ex.length)verdict=`<div class="uu" style="color:var(--red)">❌ Код прямо исключён из позиции (${esc(prefCodeList(p.ex,6))}) — преференция не предоставляется</div>`;
        else if(p.exPart.length)verdict=`<div class="uu" style="color:var(--orange)">⚠️ Позиция входит в перечень не целиком: исключены ${esc(prefCodeList(p.exPart,20))}. Введите полный 10-значный код, чтобы получить однозначный ответ</div>`;
        else verdict=`<div class="uu" style="color:var(--green)">✅ Код входит в перечень преференциальных товаров</div>`;
        const fnNote=p.fn?`<div class="uu">Для этой позиции перечень требует руководствоваться <strong>и кодом, и наименованием товара</strong> (сноска 2 к перечню), поэтому одного совпадения кода недостаточно</div>`:'';
        const un=p.ex.length?esc(title):esc(title)+' — '+esc(rateTxt);
        rows+=`<div class="usir-row"><div class="un">${un}</div><div class="uu">Позиция перечня: <strong>${esc(pos)}</strong> — ${esc(p.name)}</div>${verdict}${fnNote}</div>`;
      }
      return rows;
    };
    const devRate=ettR===null?'75% от ставки ЕТТ':(ettR===0?'75% от ставки ЕТТ, но ставка ЕТТ по этому коду и так 0% — преференция ничего не меняет':'75% от ставки ЕТТ, то есть '+pct(ettR*0.75)+'% вместо '+pct(ettR)+'%');
    const cList=(a,t)=>`<details style="margin-top:6px"><summary style="cursor:pointer;font-size:11px;color:var(--indigo)">${esc(t)} (${a.length})</summary><div style="margin-top:6px;font-size:11px;line-height:1.55">${a.map(esc).join(' · ')}</div></details>`;
    html+=`<div class="card c-ett" data-dir="im" data-kind="tariff" data-cty="estp"><div class="rh"><div class="ico">🌍</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">Единая система тарифных преференций ЕАЭС — пониженная ставка для товаров из развивающихся и наименее развитых стран</div><div class="tags"><span class="tag t-ett">🌍 Преференция ЕСТП</span></div><div class="ett-rate">${esc(headTxt)}</div><div class="usir-list">${block(devH,'Развивающиеся страны ('+PREF_DEV_C.length+')',devRate)}${block(ldcH,'Наименее развитые страны ('+PREF_LDC_C.length+')','0% — пошлина не взимается')}</div><div class="det"><strong>Важно:</strong> преференция применяется не к коду как таковому, а только к товару, ПРОИСХОДЯЩЕМУ из страны-пользователя ЕСТП. По пункту 65 Правил определения происхождения одновременно должны выполняться четыре условия: товар включён в перечень преференциальных товаров; происхождение подтверждено сертификатом (по форме приложения № 2 к Правилам; срок применения — 12 месяцев с даты выдачи), а при таможенной стоимости партии не более 5 000 евро — декларацией о происхождении товара; соблюдено требование прямой поставки (пункты 67–70: перевозка через третьи страны допускается, если товар был под таможенным контролем, не продавался и не подвергался операциям, кроме сохранности и перегрузки); страна-пользователь соблюдает требования административного сотрудничества. <strong>Прямой закупки не требуется</strong> — по пункту 66 товар можно приобрести и у лица, зарегистрированного в любой другой стране. Критерий достаточной переработки: стоимость непроисходящих материалов не более 50% (развивающиеся страны) или 60% (наименее развитые) стоимости товара на условиях «франко-завод». Иран и Монголия входят в перечень развивающихся стран и одновременно имеют собственные соглашения с ЕАЭС — по ним смотрите отдельные карточки.<br>${cList(PREF_DEV_C,'Перечень развивающихся стран')}${cList(PREF_LDC_C,'Перечень наименее развитых стран')}<strong>Источники:</strong> ${docLink('пункты 2 и 3 статьи 36 Договора о ЕАЭС от 29.05.2014',DOC_SOURCES.eaeuTreaty)} (ставки 75% и 0%); ${docLink('перечень преференциальных товаров — Решение Совета ЕЭК №8 от 13.01.2017, сводная публикация ЕЭК по состоянию на 08.03.2026',DOC_SOURCES.prefGoods)}; ${docLink('перечни стран — приложения 2 и 3 к Решению КТС №130 в ред. Решения Совета ЕЭК №8 от 28.01.2026, сводная публикация ЕЭК от 15.05.2026',DOC_SOURCES.prefCountries)}; ${docLink('Положение о ЕСТП — Решение Совета ЕЭК №47 от 06.04.2016 в ред. №122 от 19.12.2019 и №102 от 27.11.2025',DOC_SOURCES.prefPolozhenie)}; ${docLink('Правила определения происхождения товаров из развивающихся и наименее развитых стран — Решение Совета ЕЭК №60 от 14.06.2018 в ред. №49 от 14.05.2024',DOC_SOURCES.prefRules)}.${auditNote('pref')}</div></div>`;
  }


  // Акциз (статьи 334 и 336 НК КР)
  if(exciseList.length>0){
    let rowsHtml='';
    for(const r of exciseList){
      const rn=r[0],rname=r[1],rcodes=r[2],runit=r[3],rrate=r[4],rnote=r[5],rsched=r[8];
      const schedHtml=rsched?`<div class="uu">График ставок по акту: ${rsched.map(s=>esc(s[0])+' — '+esc(String(s[1]))+' сом').join('; ')}</div>`:'';
      const noteHtml=rnote?`<div class="uu">${esc(rnote)}</div>`:'';
      rowsHtml+=`<div class="usir-row"><div class="un">п.${esc(rn)} — ${esc(rname)}</div><div class="uu">Коды по акту: ${esc(rcodes)} · налоговая база: ${esc(runit)}</div><div class="uvals"><span class="usir-val"><b>Базовая ставка:</b> ${esc(String(rrate))} сом / ${esc(runit)}</span></div>${schedHtml}${noteHtml}</div>`;
    }
    const many=exciseList.length>1?'<div class="ett-more">Коду отвечает несколько пунктов статьи 336: акт различает их по виду товара, а не по коду, — выберите пункт по описанию своего товара.</div>':'';
    html+=`<div class="card c-ex" data-dir="im"><div class="rh"><div class="ico">🍶</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">Товар подакцизный — найдено пунктов: ${exciseList.length}</div><div class="tags"><span class="tag t-ex">🍶 Акциз (ст.334, 336 НК КР)</span></div><div class="usir-list">${rowsHtml}</div>${many}<div class="det">Акциз платят и производитель в Кыргызской Республике, и импортёр (ст.331, 333 НК КР); налоговая база — физический объём товара (ст.335), а не его стоимость. Ставка считается сверх пошлины и <strong>входит в облагаемую стоимость импорта</strong>, то есть увеличивает и НДС: ст.310 для ввоза из третьих стран, ч.4 ст.311 для ввоза из ЕАЭС. Приведена <em>базовая</em> ставка: по ч.2 ст.336 Кабинет Министров вправе установить ставку ниже её в пределах базовой, поэтому перед уплатой стоит проверить действующий размер. Источник — ${docLink('Налоговый кодекс КР, ст.336',DOC_SOURCES.nk)}.</div>${auditNote('excise')}</div>`;
  }

  // Налоговая база НДС с признаками риска (перечень ГНС по ст.307 НК КР)
  if(nbndsList.length>0){
    const shown=nbndsList.slice(0,15);
    let rowsHtml='';
    for(const r of shown){
      const [rn,rc,rname,runit,rval]=r;
      rowsHtml+=`<div class="usir-row"><div class="un">${rn?'поз. '+rn+' — ':''}${esc(fmtCode(rc))} — ${esc(trunc(rname,120))}</div><div class="uu">Единица измерения по акту: ${esc(runit)}</div><div class="uvals"><span class="usir-val"><b>Налоговая база НДС:</b> ${esc(String(rval))} сом / ${esc(runit.toLowerCase())}</span></div></div>`;
    }
    const moreNote=nbndsList.length>shown.length?`<div class="ett-more">Показаны первые ${shown.length} из ${nbndsList.length} позиций — введите больше цифр кода, чтобы уточнить</div>`:'';
    html+=`<div class="card c-usir" data-dir="im" data-eaeu-only="1"><div class="rh"><div class="ico">🧾</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">Установлена налоговая база НДС, имеющая признаки риска — найдено ${nbndsList.length} позиций</div><div class="tags"><span class="tag t-usir">🧾 НБ НДС · ввоз из ЕАЭС</span></div><div class="usir-list">${rowsHtml}</div>${moreNote}<div class="det"><strong>Что это значит.</strong> При ввозе товара из государств-членов ЕАЭС, если цена в договоре и товаросопроводительных документах <em>ниже</em> указанной базы, НДС исчисляется по ней, а не по заявленной цене; если цена выше — по заявленной (п.11 Порядка). То же правило действует для облагаемой поставки товара производителем внутри Кыргызской Республики (п.13). К крупным налогоплательщикам база с признаками риска не применяется (п.19). Импортёр, не согласный с базой, вправе обратиться в налоговый орган по месту налоговой регистрации; подтверждение цены компетентным налоговым органом страны экспортёра действует последующие 6 месяцев (п.21, п.23).<br><br><strong>Границы применения.</strong> Это <em>налоговая</em> база НДС по взаимной торговле в ЕАЭС, а не таможенная стоимость: на импорт из третьих стран, оформляемый таможней, перечень не распространяется. Сама база определяется как среднеарифметическая цена по заявлениям о ввозе за последние 60 дней, уменьшенная на 30 % (п.6 и п.8 Порядка), и пересматривается ежеквартально, а по обращениям налогоплательщиков и бизнес-ассоциаций — ежемесячно (п.9), поэтому перед декларированием значение стоит сверить с действующей редакцией приказа: ${docLink('перечень на sti.gov.kg','https://sti.gov.kg/section/0/%D0%B5%D0%B2%D1%80%D0%B0%D0%B7%D0%B8%D0%B9%D1%81%D0%BA%D0%B8%D0%B9_%D1%8D%D0%BA%D0%BE%D0%BD%D0%BE%D0%BC%D0%B8%D1%87%D0%B5%D1%81%D0%BA%D0%B8%D0%B9_%D1%81%D0%BE%D1%8E%D0%B7')}, ${docLink('Порядок (пост. КМ КР № 60)',DOC_SOURCES.pkm60)}.</div>${auditNote('nbnds')}</div>`;
  }

  // Антидемпинг
  if(adList.length>0){
    let rows='';
    for(const rec of adList){
      const [codes,country,product,rate,decision,url,until]=rec;
      const isUnclear=product && product.startsWith('⚠️');
      const decisionHtml=decision?(url?docLink(decision,url):esc(decision)):'';
      rows+=`<div class="usir-row"><div class="un">${esc(product)}${adActive(rec,dateIso)?'':` — <span style="color:var(--muted)">срок истёк ${esc(until.split('-').reverse().join('.'))}</span>`}</div><div class="uu">${country?('Страна: '+esc(country)+' · '):''}${rate?('Ставка: '+esc(rate)+' · '):''}${decisionHtml}</div></div>`;
    }
    html+=`<div class="card c-ex" data-dir="im" data-kind="tariff" data-cty="${esc(adList.map(r=>String(r[1]||"")).join(" ").toLowerCase())}"><div class="rh"><div class="ico">⚠️</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">Код входит в перечень товаров, по которым применялись/применяются антидемпинговые меры ЕАЭС</div><div class="tags"><span class="tag t-ex">⚠️ Антидемпинг</span></div><div class="usir-list">${rows}</div><div class="det"><strong>Важно:</strong> база сверена 24.09.2026 с реестром мер защиты внутреннего рынка ЕЭК (все 28 действующих мер) и по текстам решений; расхождение с реестром дозор источников проверяет ежедневно. Перед декларированием сверьте ставку для своего производителя по действующему решению на remedies.eaeunion.org; по товарным позициям (4 знака) мера определяется наименованием товара. Позиции с пометкой ⚠️ «требует уточнения» — код найден в исходном перечне, но конкретная мера/страна не установлены.</div></div>`;
  }
  // Тарифные квоты (объёмы льготного ввоза по странам ЕАЭС на конкретный год)
  if(quotaList.length>0){
    let rows='';
    for(const rec of quotaList){
      const [codes,name,year,unit,vol,note,url]=rec;
      const fmtVol=v=>v===null||v===undefined?'не установлен':esc(String(v).replace('.',','))+' '+esc(unit);
      const kgHtml=`<div class="usir-row" style="background:rgba(31,163,77,.08);border-radius:8px"><div class="un">🇰🇬 Кыргызская Республика</div><div class="uu" style="font-size:15px;font-weight:600">${fmtVol(vol.KG)}</div></div>`;
      const othersHtml=`<div class="uu" style="margin-top:6px">Армения: ${fmtVol(vol.AM)} · Беларусь: ${fmtVol(vol.BY)} · Казахстан: ${fmtVol(vol.KZ)} · Россия: ${fmtVol(vol.RU)}</div>`;
      const noteHtml=note?docLink(note,url):'';
      rows+=`<div class="usir-row"><div class="un">${esc(name)} — квота на ${year} год</div>${kgHtml}${othersHtml}<div class="uu" style="margin-top:6px">${noteHtml}</div></div>`;
    }
    html+=`<div class="card c-eec" data-dir="im" data-kind="tariff"><div class="rh"><div class="ico">📦</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">Код входит в перечень товаров с установленной тарифной квотой ЕАЭС</div><div class="tags"><span class="tag t-eec">📦 Тарифная квота</span></div><div class="usir-list">${rows}</div><div class="det"><strong>Важно:</strong> квота — это объём, в пределах которого при ввозе применяется пониженная (обычно нулевая или сниженная) ставка пошлины; сверх объёма квоты действует обычная ставка ЕТТ. Распределение квоты между участниками ВЭД внутри страны устанавливается национальным уполномоченным органом КР — уточняйте актуальный остаток там же.</div>${auditNote('quota')}</div>`;
  }

  // Триггерная защитная мера (временная отмена тарифной преференции по ЗСТ)
  if(triggerList.length>0){
    let rows='';
    // Истёкшие меры показываются наравне с действующей, но помечены: по этим товарам
    // мера вводилась четырежды, и знать историю полезнее, чем видеть пустую карточку.
    for(const rec of triggerList){
      const [codes,country,product,note,url,active]=rec;
      const noteHtml=url?docLink(note,url):esc(note);
      const badge=active?'<span style="color:var(--red);font-weight:600">действует</span>':'<span style="color:var(--muted)">истекла</span>';
      rows+=`<div class="usir-row"><div class="un">${esc(product)} — ${badge}</div><div class="uu">${country?('Страна: '+esc(country)+' · '):''}${noteHtml}</div></div>`;
    }
    const trigActive=triggerList.some(r=>r[5]);
    html+=`<div class="card c-ex" data-dir="im" data-kind="tariff" data-cty="${esc(triggerList.map(r=>String(r[1]||"")).join(" ").toLowerCase())}"><div class="rh"><div class="ico">⏸️</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">${trigActive?'Код входит в перечень товаров, по которым временно приостановлена тарифная преференция (триггерная защитная мера)':'По этому коду триггерная защитная мера вводилась, но сейчас не действует'}</div><div class="tags"><span class="tag t-ex">⏸️ Триггерная защитная мера</span></div><div class="usir-list">${rows}</div><div class="det"><strong>Важно:</strong> это не антидемпинговая пошлина и не постоянная мера — на срок действия решения (обычно 6 месяцев) вместо льготной ставки по соглашению о свободной торговле применяется обычная ставка ЕТТ ЕАЭС; по истечении срока преференция восстанавливается автоматически. Сроки в записях посчитаны от даты вступления решения в силу по сроку, который назван в самом решении, — в тексте решения конечная дата не пишется, поэтому перед декларированием сверьте её. Меры по одежде из Вьетнама вводились четырежды: № 20 от 07.02.2018, № 85 от 06.07.2021, № 74 от 26.08.2025 и № 47 от 20.04.2026.${auditNote('trigger')}</div></div>`;
  }

  // Товарные знаки в таможенном реестре ОИС (ТРОИС ГТС)
  if(troisList.length>0){
    const nAct=troisList.filter(h=>h.rec[4]===1).length;
    let rows='';
    for(const h of troisList.slice(0,12))rows+=troisRowHtml(h.rec,h.code);
    const more=troisList.length>12?`<div class="uu" style="margin-top:8px">…и ещё ${troisList.length-12} записей по этому коду — весь перечень в самом реестре.</div>`:'';
    const head=nAct>0?`По этому коду в таможенном реестре ОИС есть действующие товарные знаки (${nAct} из ${troisList.length} записей по коду)`:'По этому коду записи в таможенном реестре ОИС есть, но все они исключены или их срок истёк';
    const tg=nAct>0?'<span class="tag t-srt">🛡️ Товарный знак в ТРОИС</span>':'<span class="tag t-usir">🛡️ ТРОИС — записи недействующие</span>';
    html+=`<div class="card c-srt"><div class="rh"><div class="ico">🛡️</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">${head}</div><div class="tags">${tg}</div><div class="usir-list">${rows}${more}</div>${troisDetHtml()}</div>`;
  }


  // Решения ЕЭК по классификации товара
  if(eecDecList.length>0){
    let rows='';
    for(const d of eecDecList.slice(0,10)){
      const [num,codes,dec,date,name,url]=d;
      const decLabel=docLink(dec+(date?' от '+date:''),url);
      rows+=`<div class="usir-row"><div class="un">${esc(name)}</div><div class="uu">Решение ${decLabel} · коды: ${codes.map(c=>esc(fmtCode(c))).join(', ')}</div></div>`;
    }
    html+=`<div class="card c-eec"><div class="rh"><div class="ico">📋</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">Найдены решения ЕЭК по классификации этого товара (${eecDecList.length})</div><div class="tags"><span class="tag t-eec">📋 Решение ЕЭК</span></div><div class="usir-list">${rows}</div><div class="det">${auditNote('eecdec')}</div></div>`;
  }

  // Коэффициент для товаров из КНР
  if(kefHit){
    html+=`<div class="card c-usir" data-dir="im" data-kind="tariff" data-cty="китай кнр"><div class="rh"><div class="ico">🇨🇳</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">Коэффициент для товаров из КНР: ×${esc(String(kefHit.coef))}</div><div class="tags"><span class="tag t-usir">🇨🇳 ${esc(kefHit.group)}</span></div><div class="det">Применяется как множитель к стоимостному индикатору риска при поставках из Китая. Ссылка на публикацию коэффициентов в базе пока не указана — значение справочное.${auditNote('kef')}</div></div>`;
  }

  // Запреты/льготы
  for(const e of bans){
    let cc,tags='',dets='';
    const exOn=banOn(e,'ex',dateIso),imOn=banOn(e,'im',dateIso),today=dateIso||new Date(Date.now()+6*3600e3).toISOString().slice(0,10),dmy=d=>d.split('-').reverse().join('.'),quotaOut=!!(e.льгOut&&today>=e.льгOut);
    if(exOn&&imOn)cc='c-both';
    else if(exOn)cc='c-ex';
    else if(imOn)cc='c-im';
    else if(banOn(e,'льг',dateIso))cc=quotaOut?'c-eec':'c-льг';
    else cc='c-ok';
    // Совпадение с «из», неподтверждённое основание, исключение акта или дата раньше начала
    // известной редакции — не запрет, а повод проверить: тег без красного, карточка вне группы «Запреты».
    const qn10=norm(qt).replace(/\D/g,'');
    const exc=!!(e.exExcept&&e.exExcept.some(c=>qn10.startsWith(c)||c.startsWith(qn10)));
    const sideFrom=side=>e[side+'From']||((/(?:^|\s)с\s+(\d{2})\.(\d{2})\.(\d{4})/.exec(e[side+'N']||'')||[]).slice(1).reverse().join('-')||'');
    const hist=!!(dateIso&&((exOn&&sideFrom('ex')&&dateIso<sideFrom('ex'))||(imOn&&sideFrom('im')&&dateIso<sideFrom('im'))));
    const soft=!!(e.partial||e.unver||exc||hist);
    if(soft&&(exOn||imOn))cc='c-eec';
    const softTag=word=>e.unver?`<span class="tag t-eec-dual">❓ Запрет ${word} не подтверждён первоисточником</span>`
      :hist?`<span class="tag t-eec-dual">❔ На ${dmy(dateIso)} база не хранит редакций запрета ${word} (известная редакция — с ${dmy(sideFrom(word==='вывоза'?'ex':'im'))})</span>`
      :exc?`<span class="tag t-eec-dual">⚠️ Исключение из запрета ${word} — при условии акта</span>`
      :`<span class="tag t-eec-dual">⚠️ Возможный запрет ${word} («из» — проверьте по наименованию)</span>`;
    if(exOn)tags+=soft?softTag('вывоза'):`<span class="tag t-ex">⛔ Запрет вывоза</span>`;
    if(imOn)tags+=soft?softTag('ввоза'):`<span class="tag t-im">⚠️ Запрет ввоза</span>`;
    for(const [side,word] of [['ex','вывоза'],['im','ввоза']]){
      if(!e[side]||banOn(e,side,dateIso))continue;
      const u=e[side+'Until'],f=e[side+'From'];
      tags+=`<span class="tag t-eec-dual">${u&&today>u?`⏳ Срок запрета ${word} истёк ${dmy(u)} — продление в базе не найдено`:`⏸ Запрет ${word} действует с ${dmy(f)}`}</span>`;
    }
    if(e.льг)tags+=banOn(e,'льг',dateIso)?(quotaOut?`<span class="tag t-eec-dual">⏹ Квота льготы исчерпана (счётчик ГТС на ${dmy(e.льгOut)}) — пошлина по ЕТТ</span>`:`<span class="tag t-льг">💠 Льготный ввоз</span>`):`<span class="tag t-eec-dual">⏳ Срок льготы истёк ${dmy(e.льгUntil)}</span>`;
    if(!e.ex&&!e.im&&!e.льг)tags+=`<span class="tag t-ok">✓ Разрешён</span>`;
    if(exc)dets+=`<div><strong>Исключение:</strong> ${esc(e.exExceptN||'')}</div>`;
    if(e.exExceptCty)dets+=`<div><strong>Исключение по стране назначения:</strong> ${esc(e.exExceptCtyN||'')}</div>`;
    if(e.imExceptEaeu)dets+=`<div><strong>Исключение:</strong> запрет не распространяется на товары, ввозимые с территории государств-членов ЕАЭС (по тексту акта)</div>`;
    if(e.exN)dets+=`<div><strong>Вывоз:</strong> ${esc(e.exN)}</div>`;
    if(e.imN)dets+=`<div><strong>Ввоз:</strong> ${esc(e.imN)}</div>`;
    if(e.льгN)dets+=`<div><strong>Льгота:</strong> ${esc(e.льгN)}</div>`;
    if(e.exN||e.imN||e.льгN){
      const dUrl=e.docUrl||NPA_REGISTRY_URL;
      const dLabel=e.docLabel||(e.docUrl?'Официальный текст постановления':'Реестр НПА Кабинета Министров КР — найдите акт по номеру');
      dets+=`<div><strong>Документ:</strong> ${docLink(dLabel,dUrl)}</div>`;
    }
    html+=`<div class="card ${cc}"${(e.im||e.ex)?` data-dir="${[e.im?'im':'',e.ex?'ex':''].filter(Boolean).join(' ')}"`:(e.льг?' data-dir="im" data-kind="tariff"':'')}${soft?' data-partial="1"':''}${e.imExceptEaeu?' data-except-eaeu="1"':''}${e.exExceptCty?` data-except-cty="${esc(e.exExceptCty)}" data-except-cty-note="${esc(e.exExceptCtyN||'')}"`:''}><div class="rh"><div class="ico">${e.ico||'📦'}</div><div><div class="rc">${esc(e.codes[0])}</div></div></div><div class="rn">${esc(e.name)}</div><div class="tags">${tags}</div>${dets?`<div class="det">${dets}${auditNote('ban')}</div>`:''}</div>`;
  }

  // НКС
  for(const n of nksList){
    const secs=[...new Set(n.items.map(i=>NKS_SECS[NKS_ITEMS[i][1]]).filter(Boolean))];
    let permitNote='';
    let pos=null;
    const secTxt=secs.join(' ');
    if(/крипт|Защита информации/i.test(secTxt))pos='2.19';
    else if(/Телекоммуникац/i.test(secTxt))pos='2.16';
    if(pos){
      const p=permitOrgByPos(pos);
      if(p)permitNote=`<div><strong>Разрешительный орган (п.${esc(p.pos)} Единого перечня):</strong> ${esc(p.org)}</div>`;
    }
    const shown=n.items.slice(0,6);
    const itemsHtml=shown.map(i=>{const it=NKS_ITEMS[i];return `<li>${it[2]?`<strong>п. ${esc(it[2])}</strong> — `:''}${esc(it[3])}</li>`}).join('');
    const moreItems=n.items.length>shown.length?`<div class="more-hint">…и ещё ${n.items.length-shown.length} позиц. этого списка</div>`:'';
    const codesTxt=n.codes.slice(0,10).map(x=>fmtCode(x)).join(', ')+(n.codes.length>10?' и др.':'');
    // Предупреждение нужно и тогда, когда устаревший код акта совпал напрямую:
    // устарел он от этого не меньше. Поэтому смотрим на TNVED_MAP, а не на то,
    // каким путём код нашёлся.
    const obsolete=n.codes.filter(x=>TNVED_MAP[x]);
    const legacyHtml=obsolete.map(x=>legacyNote(x,n.legacyAt,'Это не означает, что товар обязательно контролируется, — сверьте наименование товара с текстом списка.')).join('')
      +(n.legacy&&!obsolete.length?legacyNote(n.codes[0],n.legacyAt,'Сверьте наименование товара с текстом списка.'):'');
    if(n.unver){
      html+=`<div class="card c-nks"><div class="rh"><div class="ico">❓</div><div><div class="rc">${esc(codesTxt)}</div></div></div><div class="rn">Код есть в наборе НКС приложения, но не подтверждён действующей редакцией акта</div><div class="tags"><span class="tag t-nks">❓ не подтверждено первоисточником</span></div><div class="det"><div><strong>Что это значит:</strong> код совпал с набором НКС, который вёлся в этом приложении, но при построчной сверке 05.09.2026 он не найден ни в одной из трёх редакций Национального контрольного списка (10.02.2023, 26.12.2024, 08.10.2025). Происхождение кода не установлено, поэтому утверждать, что позиция подпадает под экспортный контроль КР, нельзя.</div><div><strong>Что делать:</strong> проверьте товар по официальному тексту списка и при сомнении обратитесь в уполномоченный орган по экспортному контролю.</div><div><strong>Документ:</strong> ${docLink('Пост. Кабинета Министров КР № 63 от 10.02.2023 (в ред. от 08.10.2025)',DOC_SOURCES.nks63)}</div><div class="more-hint">Сверка набора с первоисточником: 05.09.2026.</div></div></div>`;
      continue;
    }
    html+=`<div class="card c-nks"${n.codes.some(c=>c.length>=9)?'':' data-partial="1"'}><div class="rh"><div class="ico">${NKS_ICONS[n.list]||'🔐'}</div><div><div class="rc">${esc(codesTxt)}</div></div></div><div class="rn">${esc(NKS_LISTS[n.list])}</div><div class="tags"><span class="tag t-nks">🔐 Требует лицензии</span>${n.codes.some(c=>c.length>=9)?'':'<span class="tag t-nks">⚠️ код акта короче — проверьте по наименованию</span>'}${legacyHtml?'<span class="tag t-nks">⚠️ код акта устарел</span>':''}</div><div class="det">${legacyHtml}<div><strong>Позиции списка, под которые попал код:</strong><ul class="note-list">${itemsHtml}</ul></div>${moreItems}${secs.length?`<div><strong>Раздел списка:</strong> ${esc(secs.slice(0,3).join('; '))}</div>`:''}<div><strong>Документ:</strong> ${docLink('Пост. Кабинета Министров КР № 63 от 10.02.2023 (в ред. от 08.10.2025, с изм. № 243 от 15.05.2024, № 804 от 26.12.2024, № 649 от 08.10.2025)',DOC_SOURCES.nks63)}</div><div><strong>Требование:</strong> Экспорт, импорт, реэкспорт и транзит контролируемой продукции — по лицензии или разрешению уполномоченного органа КР (ст. 11 Закона КР от 23.01.2003 № 30 «Об экспортном контроле», ред. 15.02.2023: «внешнеэкономические операции, предусматривающие экспорт, импорт, реэкспорт и транзит»; порядок выдачи определяет Кабинет Министров). Совпадение по коду — повод сверить наименование и характеристики товара с пунктом списка</div>${permitNote}${auditNote('nks')}</div></div>`;
  }

  // Лекарственные средства (НДС 0%)
  if(lsList.length>0){
    // Group all matching drug names
    const allNames=[...new Set(lsList.flatMap(e=>e.names.split(',').map(n=>n.trim())))].slice(0,8);
    const codes=lsList.map(e=>e.code);
    const displayCode=lsList[0].code;
    // Все попадания — строки перечня вида «Из NNNN»? Тогда освобождена не вся
    // товарная позиция, и заголовок карточки не должен утверждать обратное.
    const lsPartial=lsList.every(e=>VATFREE_PARTIAL[String(e.code).replace(/\D/g,'')]);
    html+=`<div class="card c-ls" data-dir="im"><div class="rh"><div class="ico">💊</div><div><div class="rc">${esc(displayCode.slice(0,4))}…</div></div></div><div class="rn">Лекарственные средства — освобождение от НДС${lsPartial?' (только для названных в перечне)':''}</div><div class="tags"><span class="tag t-ls">💊 ${lsPartial?'НДС 0% — только для названных МНН':'НДС 0% при поставке и импорте'}</span></div><div class="det"><div><strong>МНН (действующие вещества):</strong> ${esc(allNames.join(', '))}${lsList.length>1?' и другие':''}</div><div><strong>Льгота:</strong> Освобождение от НДС при поставке и импорте на территорию КР</div><div><strong>Документ:</strong> Постановление КМ КР № 596 от 02.09.2026 (https://cbd.minjust.gov.kg/7-57612/edition/58090/ru) · Приложение 1 · Перечень ЛС</div><div><strong>Совпадающих кодов в перечне:</strong> ${lsList.length}</div>${lsPartial?'<div><strong>Внимание:</strong> в перечне вместо кода стоит «Из '+esc(displayCode)+'», то есть освобождена не вся товарная позиция, а только перечисленные препараты. Калькулятор по такому попаданию НДС не обнуляет.</div>':''}</div></div>`;
  }


  // Обязательная сертификация
  if(sertList.length>0){
    const names=[...new Set(sertList.map(e=>e.name))];
    const dispCode=sertList[0].code;
    html+=`<div class="card c-srt" data-dir="im"><div class="rh"><div class="ico">📋</div><div><div class="rc">${esc(norm(qt).slice(0,4))}…</div></div></div><div class="rn">Продукция, подлежащая обязательному подтверждению соответствия</div><div class="tags"><span class="tag t-srt">📋 Сертификация / Декларирование</span></div><div class="det"><div><strong>Вид продукции:</strong> ${esc(names.slice(0,3).join('; '))}</div><div><strong>Требование:</strong> Обязательная сертификация или декларирование соответствия при ввозе и реализации на территории КР</div><div><strong>Документ:</strong> ${names.some(n=>n.includes('стройматериал')) ? docLink('Закон КР № 18 от 29.01.2010 «Технический регламент «Безопасность строительных материалов, изделий и конструкций»» · Приложение 2',DOC_SOURCES.stroymat18)+' (статус на cbd.minjust.gov.kg — «утратил силу»; см. примечание в session.md)' : docLink('Пост. КМ КР от 20.05.2022 № 267 (ред. от 22.05.2024 № 260) · Приложение 2',DOC_SOURCES.sert267)}</div>${auditNote('sert')}</div></div>`;
  }

  // ТР ЕАЭС — единые перечни продукции для таможенного декларирования
  if(treaList.length>0){
    const byTr={};
    for(const e of treaList){(byTr[e.trNum]=byTr[e.trNum]||[]).push(e)}
    for(const trNum of Object.keys(byTr)){
      const items=byTr[trNum];
      // Форма — свойство позиции: один код попадает в позиции с разными формами (постельное белье — сертификат,
      // столовое — декларация или сертификат), и общая надпись на весь регламент выдавала одну за другую.
      const byForm=new Map();
      for(const e of items){const p=`${e.num}. ${e.name}`;if(!byForm.has(e.form))byForm.set(e.form,[]);if(!byForm.get(e.form).includes(p))byForm.get(e.form).push(p)}
      const posList=ps=>esc(ps.slice(0,4).join('; '))+(ps.length>4?` (+ ещё ${ps.length-4})`:'');
      const formHtml=byForm.size===1?`<div><strong>Позиция(и) перечня:</strong> ${posList([...byForm.values()][0])}</div><div><strong>Форма подтверждения:</strong> ${esc(TR_FORM_LABEL[[...byForm.keys()][0]]||'см. графу 3 перечня')}</div>`:`<div><strong>Форма подтверждения зависит от позиции перечня:</strong></div>${[...byForm].map(([f,ps])=>`<div>• <strong>${esc(TR_FORM_LABEL[f]||'см. графу 3 перечня')}</strong> — ${posList(ps)}</div>`).join('')}`;
      const partialHit=items.some(e=>e.partial);
      const notes=[...new Set(items.map(e=>e.note).filter(Boolean))];
      html+=`<div class="card c-tr" data-dir="im"><div class="rh"><div class="ico">🇪🇦</div><div><div class="rc">${esc(norm(qt).slice(0,4))}…</div></div></div><div class="rn">${esc(items[0].trName)}</div><div class="tags"><span class="tag t-tr">🇪🇦 ТР ЕАЭС — оценка соответствия</span></div><div class="det">${items[0].noList?`<div style="color:var(--yellow)"><strong>⚠ Официального перечня с кодами ТН ВЭД нет.</strong> ${esc(items[0].noList)}</div>`:''}${formHtml}${notes.length?`<div><strong>Примечание:</strong> ${esc(notes.join('; '))}</div>`:''}<div><strong>Документ-основание:</strong> ${docLink(items[0].act,items[0].url)}</div>${items[0].transition?`<div><strong>Переходный период:</strong> ${esc(items[0].transition)}</div>`:''}${partialHit?'<div style="color:var(--yellow)"><strong>⚠ Частичное совпадение ("из ...")</strong> — требуется проверка по наименованию товара, код указывает лишь товарную позицию/субпозицию целиком</div>':''}<div style="color:var(--hint);margin-top:4px">Отдельно от национального перечня сертификации КР (Пост. №267) — союзный документ ЕАЭС + маркировка EAC, проверяется дополнительно.</div>${auditNote('tr')}</div></div>`;
    }
  }

  // Медицинские изделия (НДС 0%) — Пост. № 596, Приложение 2
  if(medList.length>0){
    const names=[...new Set(medList.map(e=>e.name))].slice(0,6);
    const medPartial=medList.every(e=>VATFREE_PARTIAL[String(e.code).replace(/\D/g,'')]);
    html+=`<div class="card c-ls" data-dir="im"><div class="rh"><div class="ico">🏥</div><div><div class="rc">${esc(norm(qt).slice(0,4))}…</div></div></div><div class="rn">Медицинское изделие — освобождение от НДС${medPartial?' (только для названных в перечне)':''}</div><div class="tags"><span class="tag t-ls">🏥 ${medPartial?'НДС 0% — только для названных изделий':'НДС 0% при поставке и импорте'}</span></div><div class="det"><div><strong>Наименование:</strong> ${esc(names.join('; '))}</div><div><strong>Льгота:</strong> Освобождение от НДС при поставке и импорте на территорию КР</div><div><strong>Документ:</strong> Постановление КМ КР № 596 от 02.09.2026 (https://cbd.minjust.gov.kg/7-57612/edition/58090/ru) · Приложение 2 · Перечень медицинских изделий</div><div><strong>Совпадающих позиций:</strong> ${medList.length}</div>${medPartial?'<div><strong>Внимание:</strong> в перечне вместо кода стоит «Из …» — освобождена не вся товарная позиция, а только перечисленные изделия. Калькулятор по такому попаданию НДС не обнуляет.</div>':''}</div></div>`;
  }

  // Сырьё для производства ЛС/медизделий (НДС 0% только при импорте) — Пост. № 596, Приложение 3
  if(matList.length>0){
    const names=[...new Set(matList.map(e=>e.name))].slice(0,6);
    html+=`<div class="card c-ls" data-dir="im"><div class="rh"><div class="ico">🧪</div><div><div class="rc">${esc(norm(qt).slice(0,4))}…</div></div></div><div class="rn">Сырьё для производства ЛС/медизделий — освобождение от НДС</div><div class="tags"><span class="tag t-ls">🧪 НДС 0% только при импорте</span></div><div class="det"><div><strong>Наименование:</strong> ${esc(names.join('; '))}</div><div><strong>Льгота:</strong> Освобождение от НДС при импорте на территорию КР для использования в производстве лекарственных средств и медицинских изделий (льгота обусловлена целевым использованием, а не только кодом, поэтому калькулятор по такому попаданию НДС не обнуляет, а показывает предупреждение)</div><div><strong>Документ:</strong> Постановление КМ КР № 596 от 02.09.2026 (https://cbd.minjust.gov.kg/7-57612/edition/58090/ru) · Приложение 3 · Перечень исходных материалов</div><div><strong>Совпадающих позиций:</strong> ${matList.length}</div></div></div>`;
  }

  // Ст. 297 ч.1 НК КР — самоисполнимые льготы (коды прямо в Кодексе, без перечня КМ)
  if(art297List.length>0){
    const notes=[...new Set(art297List.map(e=>e.note))];
    html+=`<div class="card c-ls" data-dir="im"><div class="rh"><div class="ico">⚡</div><div><div class="rc">${esc(art297List[0].code.slice(0,4))}…</div></div></div><div class="rn">Освобождение от НДС при импорте — ст. 297 ч.1 НК КР</div><div class="tags"><span class="tag t-ls">⚡ НДС 0% (код указан прямо в Кодексе)</span></div><div class="det">${notes.map(n=>`<div>• ${esc(n)}</div>`).join('')}<div><strong>Документ:</strong> Налоговый кодекс КР от 18.01.2022 № 3, ст. 297 ч.1 (перечень Кабинета Министров не требуется, т.к. пункт не входит в перечень ч.2 ст.297)</div></div></div>`;
  }

  // Ст. 300 НК КР — временный ввоз воздушных судов
  if(art300List.length>0){
    const notes=[...new Set(art300List.map(e=>e.note))];
    html+=`<div class="card c-ls" data-dir="im"><div class="rh"><div class="ico">✈️</div><div><div class="rc">${esc(art300List[0].code.slice(0,4))}…</div></div></div><div class="rn">Освобождение от НДС — временный ввоз (ст. 300 НК КР)</div><div class="tags"><span class="tag t-ls">✈️ НДС 0% только при временном ввозе</span></div><div class="det">${notes.map(n=>`<div>• ${esc(n)}</div>`).join('')}<div style="color:var(--yellow)"><strong>⚠ Это не льгота на импорт для реализации</strong> — освобождение действует только в рамках таможенной процедуры временного ввоза</div><div><strong>Документ:</strong> Налоговый кодекс КР от 18.01.2022 № 3, ст. 300</div></div></div>`;
  }

  // Ст. 301 НК КР — ввоз основных средств плательщиками НДС / субъектами УСН (патент)
  if(art301Hit){
    const groupNote=art301Hit.g1&&art301Hit.g2?'Входит в товарные группы п.1 и п.2 ст.301':art301Hit.g2?'Входит в товарные группы п.2 ст.301 (только нефтепереработка/химия/нефтехимия)':'Входит в товарные группы п.1 ст.301';
    html+=`<div class="card c-ls" data-dir="im"><div class="rh"><div class="ico">🏭</div><div><div class="rc">${esc(norm(qt).slice(0,4))}…</div></div></div><div class="rn">Возможное освобождение от НДС — ввоз основного средства (ст. 301 НК КР)</div><div class="tags"><span class="tag t-ls">🏭 НДС 0% при выполнении условий</span></div><div class="det"><div><strong>${esc(groupNote)}</strong> — совпадение по коду является необходимым, но не достаточным условием</div><div><strong>Путь 1 — общий (ч.1-2 ст.301):</strong><ul class="note-list"><li>стоимость товара ≥ 5000 расчётных показателей;</li><li>ввозится плательщиком НДС или субъектом упрощённой системы (патент) как основное средство для собственных производственных целей, либо приобретено банком/лизинговой компанией для мурабаха, иджара мунтахийя биттамлик или финансового лизинга;</li>${art301Hit.g2?'<li>только для субъектов нефтеперерабатывающего, химического и нефтехимического производства;</li>':''}<li>по группе 8702 — исключая микроавтобусы; по группе 8903 — только парусные суда без двигателя или суда на электродвигателе.</li></ul></div><div><strong>Путь 2 — по статусу субъекта (ч.3 ст.301, независимо от того, является ли субъект плательщиком НДС):</strong> льгота действует на те же товарные группы (п.1 и п.2 ч.2) при ввозе для собственных производственных целей: сельскохозяйственным производителем, сельскохозяйственным кооперативом (в т.ч. для целей членов кооператива), машинно-тракторной станцией, торгово-логистическим центром сельхозназначения, либо производителем ювелирных изделий. <strong>Для сельхозпроизводителя и сельхозкооператива порог 5000 расчётных показателей по ч.6 ст.301 не применяется.</strong></div><div><strong>Документ:</strong> Налоговый кодекс КР от 18.01.2022 № 3, ст. 301 (в ред. законов № 78 от 03.04.2023, № 37 от 12.02.2025, № 185 от 31.07.2025, № 243 от 29.10.2025)</div></div></div>`;
  }

  // Ст. 297 ч.1 НК КР — товары по перечню КМ (Пост. № 131, Приложения 1,2,3,4,5)
  // Ставка НДС 0% по решениям КМ (п.2 ст.34¹ НК КР): «ставка 0%», а не «освобождение»; условная строка
  // говорит условие — по одному коду 0% не применяется, калькулятор начисляет 12%.
  {const v0=findVat0(qt);if(v0.length){
    const today=new Date(Date.now()+6*3600e3).toISOString().slice(0,10),dm=(x)=>x.split("-").reverse().join(".");
    const li=v0.map(r=>{const now=r[4].some(w=>today>=w[0]&&today<=w[1]);const per=r[4].map(w=>dm(w[0])+"–"+dm(w[1])).join(", ");
      return `<li><strong>${esc(r[2])}</strong> — ${docLink(r[0],r[1])}; периоды: ${esc(per)}${now?"":" (на сегодня не действует)"}${r[5]?`<div class="note">Только при условии: ${esc(r[6])}. По одному коду ставка 0% не применяется — калькулятор начисляет 12%.</div>`:""}</li>`;}).join("");
    const firm=v0.some(r=>!r[5]&&r[4].some(w=>today>=w[0]&&today<=w[1]));
    html+=`<div class="card c-ls" data-dir="im"${firm?"":' data-partial="1"'}><div class="rh"><div class="ico">🧾</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">Ставка НДС 0% при импорте — решение Кабинета Министров (п.2 ст.34¹ НК КР)</div><div class="tags"><span class="tag t-ls">🧾 НДС 0%${firm?"":" — при условии"}</span></div><div class="det"><ul class="note-list">${li}</ul><div><strong>Важно:</strong> это ставка НДС 0% на облагаемый импорт, а не освобождение. При ввозе из государств ЕАЭС НДС уплачивается в налоговый орган, а не на таможне.</div>${auditNote("vat0")}</div></div>`;
  }}
  if(art297PerechenList.length>0){
    const byApp={};
    for(const e of art297PerechenList){(byApp[e.app]=byApp[e.app]||{p:e.p,title:e.title,names:[]}).names.push(e.name)}
    for(const e of art297PerechenList){if(e.unver)byApp[e.app].unver=true}
    const parts=Object.values(byApp).map(g=>`<div><strong>п.${esc(g.p)} ч.1 ст.297</strong> (Приложение ${g.unver?'':'к '}Пост. №131): ${esc([...new Set(g.names)].slice(0,5).join('; '))}${g.unver?' <span style="color:var(--red)">— приложения 11 в действующей редакции постановления № 131 (ред. 22.10.2025) нет: при построчной сверке 05.09.2026 ни само приложение, ни ссылка на него в тексте не найдены, происхождение перечня не подтверждено</span>':''}</div>`).join('');
    html+=`<div class="card c-ls" data-dir="im"><div class="rh"><div class="ico">📦</div><div><div class="rc">${esc(norm(qt).slice(0,4))}…</div></div></div><div class="rn">Освобождение от НДС при импорте — ст. 297 ч.1 НК КР (перечень КМ)</div><div class="tags"><span class="tag t-ls">📦 НДС 0% по перечню КМ</span></div><div class="det">${parts}<div><strong>Документ:</strong> Постановление КМ КР № 131 от 11.03.2022 (в ред. от 22.10.2025)</div>${auditNote('nalog')}</div></div>`;
  }

  // Ст. 298 НК КР — племенные животные / семена / удобрения / средства защиты растений
  if(art298List.length>0){
    const byApp={};
    for(const e of art298List){(byApp[e.app]=byApp[e.app]||{title:e.title,names:[]}).names.push(e.name)}
    const parts=Object.values(byApp).map(g=>`<div><strong>${esc(g.title)}</strong>: ${esc([...new Set(g.names)].slice(0,5).join('; '))}</div>`).join('');
    html+=`<div class="card c-ls" data-dir="im"><div class="rh"><div class="ico">🌾</div><div><div class="rc">${esc(norm(qt).slice(0,4))}…</div></div></div><div class="rn">Освобождение от НДС при импорте — ст. 298 НК КР</div><div class="tags"><span class="tag t-ls">🌾 НДС 0% до 01.01.2030</span></div><div class="det">${parts}<div><strong>Документ:</strong> Постановление КМ КР № 131 от 11.03.2022 (в ред. от 22.10.2025)</div>${auditNote('nalog')}</div></div>`;
  }

  // Ст. 299 НК КР — вооружение, военная техника, спецсредства
  if(art299List.length>0){
    const names=[...new Set(art299List.map(e=>e.name))].slice(0,5);
    html+=`<div class="card c-ls" data-dir="im"><div class="rh"><div class="ico">🛡️</div><div><div class="rc">${esc(norm(qt).slice(0,4))}…</div></div></div><div class="rn">Возможное освобождение от НДС — ст. 299 НК КР</div><div class="tags"><span class="tag t-ls">🛡️ НДС 0% только для гос. органов</span></div><div class="det"><div><strong>Наименование:</strong> ${esc(names.join('; '))}</div><div><strong>Условие:</strong> льгота — только для товаров, ввозимых государственными органами/организациями КР, финансируемыми из госбюджета, в целях обороноспособности, нацбезопасности и правопорядка</div><div><strong>Документ:</strong> Постановление КМ КР № 131 от 11.03.2022 (в ред. от 22.10.2025) · Приложение 12</div></div></div>`;
  }

  // Вакцины и лекарства для животных (Пост. № 131, Приложение 6)
  if(app6VetList.length>0){
    const names=[...new Set(app6VetList.map(e=>e.name))].slice(0,6);
    html+=`<div class="card c-ls" data-dir="im"><div class="rh"><div class="ico">🐄</div><div><div class="rc">${esc(norm(qt).slice(0,4))}…</div></div></div><div class="rn">Вакцины/лекарственные средства для животных — освобождение от НДС</div><div class="tags"><span class="tag t-ls">🐄 НДС 0% при поставке и импорте</span></div><div class="det"><div><strong>Наименование:</strong> ${esc(names.join('; '))}</div><div><strong>Документ:</strong> Постановление КМ КР № 131 от 11.03.2022 (в ред. от 22.10.2025) · Приложение 6 (может частично пересекаться с Пост. № 596 от 02.09.2026, специально посвящённым п.13 ч.1 ст.297)</div></div></div>`;
  }

  // Ст. 297 ч.1 п.20 НК КР — оборудование для ВИЭ (ВЭС/СЭС/МГЭС) — Пост. №196 от 04.10.2021 (в ред. №272 от 22.04.2026)
  if(art297P20List.length>0){
    const names=[...new Set(art297P20List.map(e=>e.name))].slice(0,6);
    html+=`<div class="card c-ls" data-dir="im"><div class="rh"><div class="ico">🌬️</div><div><div class="rc">${esc(norm(qt).slice(0,4))}…</div></div></div><div class="rn">Оборудование для энергоустановок на ВИЭ — освобождение от НДС при импорте (п.20 ч.1 ст. 297 НК КР)</div><div class="tags"><span class="tag t-ls">🌬️ НДС 0% при импорте</span></div><div class="det"><div><strong>Наименование:</strong> ${esc(names.join('; '))}</div><div><strong>Документ:</strong> Постановление КМ КР № 196 от 04.10.2021 (в актуальной редакции с изм. от 22.04.2026 № 272) · Перечень специализированных товаров и оборудования для строительства ВЭС/СЭС/МГЭС и прочего оборудования</div></div></div>`;
  }

  // Ст. 297 ч.1 п.26 НК КР — товары для развития спорта — Пост. №709 от 22.11.2024 (в актуализированной ред.)
  if(art297P26List.length>0){
    const names=[...new Set(art297P26List.map(e=>e.name))].slice(0,6);
    html+=`<div class="card c-ls" data-dir="im"><div class="rh"><div class="ico">🏅</div><div><div class="rc">${esc(norm(qt).slice(0,4))}…</div></div></div><div class="rn">Товары для развития спорта — освобождение от НДС (п.26 ч.1 ст. 297 НК КР)</div><div class="tags"><span class="tag t-ls">🏅 НДС 0% только для субъектов из перечня</span></div><div class="det"><div><strong>Наименование:</strong> ${esc(names.join('; '))}</div><div style="color:var(--yellow)"><strong>⚠ Условие:</strong> льгота применяется только при поставке/импорте лицами, включёнными в отдельные перечни субъектов-поставщиков и субъектов-импортёров (утверждены тем же постановлением) — совпадение по коду не означает автоматическое освобождение</div><div><strong>Документ:</strong> Постановление КМ КР № 709 от 22.11.2024 «О мерах по реализации требований статей 296, 297 и 364 НК КР» (Перечень товаров, в актуальной редакции)</div></div></div>`;
  }

  // Ст. 297 ч.1 п.30 НК КР — оборудование для ювелирного производства — Пост. №366 от 25.05.2026
  if(art297P30List.length>0){
    const names=[...new Set(art297P30List.map(e=>e.name))].slice(0,6);
    html+=`<div class="card c-ls" data-dir="im"><div class="rh"><div class="ico">💍</div><div><div class="rc">${esc(norm(qt).slice(0,4))}…</div></div></div><div class="rn">Оборудование/технологии/реактивы для ювелирного производства — освобождение от НДС (п.30 ч.1 ст. 297 НК КР)</div><div class="tags"><span class="tag t-ls">💍 НДС 0% только для субъектов из перечня</span></div><div class="det"><div><strong>Наименование:</strong> ${esc(names.join('; '))}</div><div style="color:var(--yellow)"><strong>⚠ Условие:</strong> льгота применяется только при импорте субъектами, включёнными в перечень субъектов ювелирного производства (Приложение 1 к тому же постановлению) — совпадение по коду не означает автоматическое освобождение</div><div><strong>Документ:</strong> Постановление КМ КР № 366 от 25.05.2026 · Приложение 2 (действует с 05.06.2026)</div></div></div>`;
  }

  // ЕАЭС Решение №30 - запреты и разрешительный порядок ЕЭК (источник: NTM_DB)
  if(eecList.length>0){
    const banItems=eecList.filter(e=>e.regime==='ban');
    const licItems=eecList.filter(e=>e.regime==='license');
    const quotaItems=eecList.filter(e=>e.regime==='quota');
    const notesHtml=(items,limit=8)=>{
      const notes=[...new Set(items.map(e=>e.note).filter(Boolean))];
      if(!notes.length) return '';
      const shown=notes.slice(0,limit);
      const rest=notes.length-shown.length;
      const list=shown.map(n=>`<li>${esc(n)}</li>`).join('');
      const more=rest>0?`<div class="more-hint">+ ещё ${rest} позици${rest===1?'я':(rest<5?'и':'й')} с этим кодом — уточните наименование товара</div>`:'';
      return `<div><strong>Примечание${notes.length>1?` (${notes.length})`:''}:</strong><ul class="note-list">${list}</ul>${more}</div>`;
    };
    const namesJoin=(names,limit)=>{
      const shown=names.slice(0,limit);
      const rest=names.length-shown.length;
      return esc(shown.join('; '))+(rest>0?` <span class="more-hint">+ ещё ${rest}</span>`:'');
    };
    const partialWarn=(items)=>items.some(e=>e.partial)?'<div><strong>⚠ Внимание:</strong> код найден по совпадению с укрупнённой (родовой) товарной позицией из Единого перечня мер нетарифного регулирования — фактическое применение меры может зависеть от дополнительных условий (дата/год производства, назначение, комплектация и т.п.), указанных в наименовании категории выше</div>':'';
    if(banItems.length>0){
      const byDir={both:[],export:[],import:[]};
      banItems.forEach(e=>byDir[e.dir].push(e.name));
      const allNames=[...new Set(banItems.map(e=>e.name))];
      const sections=[...new Set(banItems.map(e=>e.section))].sort();
      const hasBoth=byDir.both.length>0,hasEx=byDir.export.length>0,hasIm=byDir.import.length>0;
      const hasPartial=banItems.some(e=>e.partial);
      let tags='';
      if(hasBoth||hasEx) tags+=`<span class="tag t-eec-ex">⛔ Запрет вывоза (ЕАЭС)</span>`;
      if(hasBoth||hasIm) tags+=`<span class="tag t-eec-im">⚠️ Запрет ввоза (ЕАЭС)</span>`;
      if(hasPartial) tags+=`<span class="tag t-eec-im">⚠️ частичное совпадение</span>`;
      html+=`<div class="card c-eec" data-scope="third"${hasPartial?' data-partial="1"':''}><div class="rh"><div class="ico">🌐</div><div><div class="rc">${esc(norm(qt).slice(0,4))}…</div></div></div><div class="rn">Единые меры нетарифного регулирования ЕАЭС</div><div class="tags">${tags}</div><div class="det"><div><strong>Категория:</strong> ${namesJoin(allNames,4)}</div><div><strong>Основание:</strong> ${docLink('Решение Коллегии ЕЭК от 21.04.2015 № 30',DOC_SOURCES.eecR30)} · Приложение 1, раздел ${esc(sections.join(', '))}</div><div><strong>Требование:</strong> Запрет ввоза и/или вывоза через таможенную территорию ЕАЭС. Применяется ко всем государствам-членам, включая КР</div>${partialWarn(banItems)}${notesHtml(banItems)}${auditNote('eec30')}</div></div>`;
    }
    if(licItems.length>0){
      // Одна карточка на направление: раздел 2.14 (лекарства) действует при ввозе, 2.4 (коллекции) — при вывозе,
      // и общая карточка «ввоз и/или вывоз» показывала требование не того направления.
      const byDirL={};
      for(const e of licItems){const d=NTM_SEC_DIR[e.section]||'im ex';(byDirL[d]=byDirL[d]||[]).push(e)}
      for(const [dirL,licItemsD] of Object.entries(byDirL)){
      const allNames=[...new Set(licItemsD.map(e=>e.name))];
      const sections=[...new Set(licItemsD.map(e=>e.section))].sort();
      const hasPartial=licItemsD.some(e=>e.partial);
      html+=`<div class="card c-eec" data-dir="${dirL}" data-scope="third"${hasPartial?' data-partial="1"':''}><div class="rh"><div class="ico">🔐</div><div><div class="rc">${esc(norm(qt).slice(0,4))}…</div></div></div><div class="rn">Разрешительный порядок ЕАЭС — ${NTM_DIR_LABEL[dirL]}</div><div class="tags"><span class="tag t-eec-lic">🔐 Требуется лицензия/заключение</span>${hasPartial?'<span class="tag t-eec-lic">⚠️ частичное совпадение</span>':''}</div><div class="det"><div><strong>Категория:</strong> ${namesJoin(allNames,4)}</div><div><strong>Основание:</strong> ${docLink('Решение Коллегии ЕЭК от 21.04.2015 № 30',DOC_SOURCES.eecR30)} · Приложение 2, раздел ${esc(sections.join(', '))}</div><div><strong>Требование:</strong> ${NTM_DIR_REQ[dirL]} (по Положению к разделу) допускается ${sections.some(s=>s==='2.16'||s==='2.19')?'при наличии лицензии, заключения (разрешительного документа) или сведений из единого реестра ЕАЭС (см. ниже)':'только при наличии лицензии или заключения (разрешительного документа)'}. Это НЕ запрет — товар пропускается при соблюдении лицензионных требований</div>${[...new Set(licItemsD.map(e=>NTM_SEC_TR[e.section]).filter(Boolean))].map(t=>`<div><strong>Транзит:</strong> ${esc(t)}</div>`).join('')}${permitOrgHtml(sections)}${ntmRegistryHtml(sections)}${partialWarn(licItemsD)}${notesHtml(licItemsD)}${auditNote('eec30')}</div></div>`;
      }
    }
    if(quotaItems.length>0){
      const allNames=[...new Set(quotaItems.map(e=>e.name))];
      const sections=[...new Set(quotaItems.map(e=>e.section))].sort();
      const hasPartial=quotaItems.some(e=>e.partial);
      html+=`<div class="card c-eec" data-dir="ex" data-scope="third"${hasPartial?' data-partial="1"':''}><div class="rh"><div class="ico">📉</div><div><div class="rc">${esc(norm(qt).slice(0,4))}…</div></div></div><div class="rn">Временное количественное ограничение (ЕАЭС)</div><div class="tags"><span class="tag t-eec-dual">📉 Квота/временное ограничение</span>${hasPartial?'<span class="tag t-eec-dual">⚠️ частичное совпадение</span>':''}</div><div class="det"><div><strong>Категория:</strong> ${namesJoin(allNames,4)}</div><div><strong>Основание:</strong> раздел ${esc(sections.join(', '))} Единого перечня мер нетарифного регулирования ЕАЭС</div>${partialWarn(quotaItems)}${notesHtml(quotaItems)}</div></div>`;
    }
  }
  // Односторонние меры Кыргызской Республики (ст. 29 и 47 Договора о ЕАЭС) по реестру ЕЭК.
  // Действующий запрет показывает и карточка BAN_DB; здесь — запись реестра со сроками
  // и протоколом. Истёкшие меры оставлены: такие запреты вводятся на полгода и продлеваются.
  // Направление карточки — по самим мерам: ввоз, вывоз или оба.
  if(uniList.length>0){
    const uniAct=uniList.filter(m=>m.act),uniExp=uniList.filter(m=>!m.act);
    const uniItems=(list,full)=>`<ul class="note-list">${list.map(m=>{
      const pt=m.part?' <span class="more-hint">(код входит в меру частично — в реестре он записан с пометкой «из»)</span>':'';
      const src=full?[m.osn,m.prot].filter(Boolean).map(x=>esc(x)).join(' · '):'';
      const by=m.code.indexOf('-')>0?`диапазон ${esc(fmtCode(m.code.split('-')[0]))} – ${esc(fmtCode(m.code.split('-')[1]))}`:`код ${esc(fmtCode(m.code))}`;
      return `<li><strong>${esc(m.mera)}</strong> — ${esc(trunc(m.tovar,220))}${pt}<div class="more-hint">Совпало по позиции реестра: ${by} · ${esc(m.srok)}${src?' · '+src:''}</div></li>`;
    }).join('')}</ul>`;
    const dirs=new Set();
    for(const m of (uniAct.length?uniAct:uniList)){if(/ввоз|импорт/i.test(m.mera))dirs.add('im');if(/вывоз|экспорт/i.test(m.mera))dirs.add('ex')}
    const dd=dirs.size?` data-dir="${[...dirs].join(' ')}"`:'';
    const expShown=uniExp.slice(0,6);
    const expMore=uniExp.length-expShown.length;
    const uniTags=uniAct.length
      ?`<span class="tag t-eec-dual">🚧 Односторонняя мера Кыргызской Республики</span>`
      :`<span class="tag t-eec-lic">🕓 Меры по этому коду истекли</span>`;
    const uniRn=uniAct.length
      ?`Односторонние меры Кыргызской Республики (реестр ЕЭК): действующих — ${uniAct.length}`
      :'Односторонние меры Кыргызской Республики (реестр ЕЭК): действующих нет, но меры вводились';
    html+=`<div class="card c-eec"${dd}${(uniAct.length?uniAct:uniList).every(m=>m.part)?' data-partial="1"':''}><div class="rh"><div class="ico">🚧</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">${esc(uniRn)}</div><div class="tags">${uniTags}</div><div class="det">`
      +(uniAct.length?`<div><strong>Действуют сейчас:</strong></div>${uniItems(uniAct,true)}`:'')
      +(uniExp.length?`<div><strong>Срок действия истёк (${uniExp.length}):</strong></div>${uniItems(expShown,false)}${expMore>0?`<div class="more-hint">…и ещё ${expMore} — реестр ведётся с 2024 года, такие меры вводятся волнами и продлеваются</div>`:''}`:'')
      +`<div><strong>Что это значит:</strong> временные запреты, количественные ограничения и разрешительный порядок, которые Кыргызская Республика вводит сама по статьям 29 и 47 Договора о ЕАЭС и о которых уведомляет ЕЭК. Действующий запрет показан и в карточке запрета; здесь — запись реестра ЕЭК со сроками, в том числе прежними: такие меры обычно вводятся на шесть месяцев и продлеваются.</div>`
      +`<div><strong>Источник:</strong> ${docLink('Сводный реестр мер, применяемых государствами-членами ЕАЭС в одностороннем порядке (ЕЭК)',DOC_SOURCES.unimeas)} · по состоянию на ${esc(UNIMEAS_ASOF)}. ЕЭК обновляет реестр примерно раз в две недели.</div>`
      +auditNote('unimeas')+`</div></div>`;
  }
  // Ветеринарный контроль (Решение КТС №317)
  if(vetList.length>0){
    const names=[...new Set(vetList.map(e=>e.name))];
    const hasPartial=vetList.some(e=>e.partial);
    const vetNotes=[...new Set(vetList.map(e=>e.note).filter(Boolean))];
    const vetNotesHtml=vetNotes.length?`<div><strong>Дополнительное требование:</strong><ul class="note-list">${vetNotes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul></div>`:'';
    html+=`<div class="card c-nks"><div class="rh"><div class="ico">🐄</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">Подлежит ветеринарному контролю (надзору)</div><div class="tags"><span class="tag t-nks">🐄 Ветконтроль</span>${hasPartial?'<span class="tag t-nks">⚠️ частичное совпадение</span>':''}</div><div class="det"><div><strong>Наименование:</strong> ${esc(names.slice(0,3).join('; '))}</div>${hasPartial?'<div><strong>Внимание:</strong> код входит в перечень частично ("из ...") — проверьте соответствие наименованию товара</div>':''}${vetNotesHtml}<div><strong>Документ:</strong> Единый перечень товаров, подлежащих ветеринарному контролю · ${docLink('Решение КТС от 18.06.2010 №317 (Приложение 1, ред. от 25.11.2022 №174)',DOC_SOURCES.vet317)}</div>${auditNote('vet')}</div></div>`;
  }
  // Временные ветеринарные ограничения — по карточке на болезнь со своими странами (data-cty), всегда
  // «возможно» (data-partial): коды — толкование слов акта, у многих стран ограничен только регион.
  // Одинаковый заголовок собирает их в одну карточку с подблоками (CARD_FAMILIES «vettemp» в checker.js).
  // Меры ветслужбы против предприятий-изготовителей: только у товаров под ветконтролем и только при ввозе.
  if(vetList.length>0&&VET_PLANT_DB.length){
    const dm=(x)=>x.split("-").reverse().join(".");
    const li=VET_PLANT_DB.map(r=>`<li><strong>${esc(r[1])}, ${esc(r[2])}</strong> — ${esc(r[3])} с ${esc(dm(r[4]))} · ${esc(r[5])}</li>`).join("");
    html+=`<div class="card c-nks" data-dir="im" data-cty="${esc([...new Set(VET_PLANT_DB.map(r=>r[0]))].join(" "))}" data-partial="1"><div class="rh"><div class="ico">🏭</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">Ветеринарные ограничения по предприятиям-изготовителям</div><div class="tags"><span class="tag t-nks">🏭 Если товар произведён этими предприятиями</span></div><div class="det"><div><strong>Меры Главного государственного ветеринарного инспектора КР против отдельных предприятий:</strong><ul class="note-list">${li}</ul></div><div><strong>Как читать:</strong> мера действует на всю подконтрольную продукцию названного предприятия, а не на код; проверьте изготовителя по ветеринарному сертификату.</div><div><strong>Источник:</strong> ${docLink("Государственная ветеринарная служба КР — «Ограничения на ввоз», лист «Предприятия» (файл от 25.08.2026)",VET_TEMP_URL)}</div>${auditNote("vettemp")}</div></div>`;
  }
  if(vetTempList.length>0){
    const groups={};
    for(const r of vetTempList){const k=r[3]+"|"+(r[5]==="ex"?"ex":"im");(groups[k]=groups[k]||[]).push(r);}
    for(const k of Object.keys(groups)){
      const g=groups[k],ex=k.endsWith("|ex");
      const dir=ex?"ex":"im tr";
      const ctys=[...new Set(g.map(r=>r[0]))].join(" ");
      const last=g.slice().sort((a,b)=>a[7]<b[7]?1:-1)[0];
      const li=g.map(r=>`<li><strong>${esc(r[1])}</strong>${r[2]?" — "+esc(r[2].length>220?r[2].slice(0,220)+"…":r[2]):""} · ${esc(r[6])}${r[8]?" (изменения: "+esc(r[8].length>160?r[8].slice(0,160)+"…":r[8])+")":""}${/tr/.test(r[5])?" · в т.ч. транзит":""}</li>`).join("");
      html+=`<div class="card c-nks" data-dir="${dir}" data-cty="${esc(ctys)}" data-partial="1"><div class="rh"><div class="ico">🦠</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">${ex?"Ветеринарное ограничение вывоза":"Временное ветеринарное ограничение ввоза"}: ${esc(k.split("|")[0])}</div><div class="tags"><span class="tag t-nks">🦠 Ограничение ветслужбы КР</span><span class="tag t-nks">⚠️ по наименованию и стране</span></div><div class="det"><div><strong>${ex?"Направление":"Страны и регионы происхождения"}:</strong><ul class="note-list">${li}</ul></div><div><strong>Что ограничено (по последнему акту):</strong> ${esc(last[9].length>600?last[9].slice(0,600)+"…":last[9])}</div><div><strong>Внимание:</strong> акты ветеринарной службы называют товары словами, коды ТН ВЭД сопоставлены по смыслу; для многих стран ограничение касается только отдельных регионов и только продукции без обработки, обезвреживающей возбудителя. Проверьте страну, регион и вид продукции по тексту ограничения.</div><div><strong>Источник:</strong> ${docLink("Государственная ветеринарная служба КР — «Ограничения на ввоз» (файл от 25.08.2026)",VET_TEMP_URL)}</div>${auditNote("vettemp")}</div></div>`;
    }
  }
  // Маркировка — требование при ввозе, не запрет: одна карточка на все режимы, что касаются кода.
  // Совпадение по товарной позиции (4–6 знаков в акте при длинном запросе) — «проверьте по наименованию».
  if(markList.length>0){
    const qn=norm(qt),dIso=(d)=>d?d.split("-").reverse().join("."):"";
    const partial=markList.some(r=>r[2].some(c=>!c.includes("-")&&c.length<qn.length&&qn.startsWith(c)));
    const li=markList.map(r=>`<li><strong>${esc(r[1])}</strong> — ${esc(r[6])}${r[4]?"; маркировка с "+esc(dIso(r[4])):""}${r[5]?"; оборот немаркированных запрещён с "+esc(dIso(r[5])):""} · ${docLink(r[7],r[8])}${r[9]?`<div class="note">${esc(r[9])}</div>`:""}</li>`).join("");
    html+=`<div class="card c-nks" data-dir="im"${partial?' data-partial="1"':""}><div class="rh"><div class="ico">🏷️</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">Обязательная маркировка при ввозе</div><div class="tags"><span class="tag t-nks">🏷️ Маркировка</span>${partial?'<span class="tag t-nks">⚠️ проверьте по наименованию</span>':""}</div><div class="det"><div><strong>Режимы:</strong><ul class="note-list">${li}</ul></div><div><strong>Когда маркировать:</strong> товар из третьих стран — до помещения под выпуск для внутреннего потребления (в том числе на складе временного хранения из реестра); из государств ЕАЭС — до ввоза в Кыргызскую Республику, а марки акцизного сбора на такой товар наносятся на заводе-изготовителе. Не требуется для товаров для личного пользования в пределах норм и при транзите (ст. 8 Соглашения о маркировке от 02.02.2018).</div>${auditNote("marking")}</div></div>`;
  }
  if(traceList.length>0){
    const qn=norm(qt),partial=traceList.every(r=>r[1].every(c=>c.length>qn.length));
    html+=`<div class="card c-nks" data-dir="im ex"${partial?' data-partial="1"':""}><div class="rh"><div class="ico">🔎</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">Прослеживаемость ЕАЭС: ${esc(traceList.map(r=>r[0]).join("; "))}</div><div class="tags"><span class="tag t-nks">🔎 Прослеживаемость — учёт, не запрет</span>${partial?'<span class="tag t-nks">⚠️ проверьте код</span>':""}</div><div class="det"><div><strong>Что нужно:</strong> с 01.09.2026 товар учитывается в системе прослеживаемости: при импорте из ЕАЭС и из третьих стран — оприходовать в модуле ЭСФ 2.0, при экспорте ЭСФ 2.0 оформляется до вывоза. Маркировать товар не нужно.</div><div><strong>Основание:</strong> ${docLink("Решение Совета ЕЭК от 26.01.2026 № 5 (перечень товаров)",traceList[0][4])}; Решение Евразийского межправительственного совета от 30.09.2025 № 5; ${docLink("ПКМ КР от 14.09.2026 № 613 «О системе прослеживаемости товаров»","https://cbd.minjust.gov.kg/7-58148/edition/58933/ru")}</div>${auditNote("marking")}</div></div>`;
  }

  // Фитосанитарный контроль (Решение КТС №318)
  if(phytoList.length>0){
    const names=[...new Set(phytoList.map(e=>e.name))];
    const hasHigh=phytoList.some(e=>e.risk==='high');
    const hasLow=phytoList.some(e=>e.risk==='low');
    const riskLabel=hasHigh&&hasLow?'Высокий и низкий риск':hasHigh?'Высокий фитосанитарный риск':'Низкий фитосанитарный риск';
    html+=`<div class="card c-nks"><div class="rh"><div class="ico">🌱</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">Подлежит карантинному фитосанитарному контролю</div><div class="tags"><span class="tag t-nks">🌱 ${esc(riskLabel)}</span></div><div class="det"><div><strong>Наименование:</strong> ${esc(names.slice(0,3).join('; '))}</div>${hasHigh?'<div><strong>Требование:</strong> Обязательное сопровождение фитосанитарным сертификатом при ввозе</div>':''}<div><strong>Документ:</strong> Перечень подкарантинной продукции · ${docLink('Решение КТС от 18.06.2010 №318 (ред. от 26.11.2025 №95)',DOC_SOURCES.phyto318)}</div>${auditNote('phyto')}</div></div>`;
  }

  // Санитарно-эпидемиологический надзор (Решение КТС №299)
  if(sanRes.sections.length>0||sanRes.reg.length>0||sanRes.sub.length>0){
    if(sanRes.sections.length>0){
      const names=sanRes.sections.map(s=>`п.${s.num}: ${s.name}`);
      html+=`<div class="card c-nks" data-dir="im" data-partial="1"><div class="rh"><div class="ico">🧪</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">Подлежит государственному санитарно-эпидемиологическому надзору</div><div class="tags"><span class="tag t-nks">🧪 СЭН</span><span class="tag t-nks">⚠️ по группе ТН ВЭД — проверьте по наименованию</span></div><div class="det"><div><strong>Категория (Раздел I):</strong> ${esc(trunc(names.slice(0,2).join('; '),220))}</div><div><strong>Документ:</strong> Единый перечень продукции, подлежащей СЭН · ${docLink('Решение КТС от 28.05.2010 №299 (ред. 02.06.2026)',DOC_SOURCES.san299)}</div>${auditNote('san')}</div></div>`;
    }
    if(sanRes.reg.length>0){
      const regItems=sanRes.reg.filter(e=>!e.excluded);
      const exclItems=sanRes.reg.filter(e=>e.excluded);
      if(regItems.length>0){
        const names=[...new Set(regItems.map(e=>e.name))];
        const hasPartial=regItems.some(e=>e.partial);
        const notes=[...new Set(regItems.map(e=>e.note).filter(Boolean))];
        const notesHtml=notes.length?`<div><strong>Примечание:</strong><ul class="note-list">${notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul></div>`:'';
        const sec3Hint=`<div style="margin-top:4px"><strong>Независимо от кода не требуется, если товар относится к Разделу III</strong> (напр. личное пользование, гуманитарная помощь, выставочные образцы не для продажи, товар бывший в употреблении, лабораторные реактивы, товар по заказу зарубежной фирмы для реализации за пределами ЕАЭС и др. — ${SAN_SECTION3.length} категорий, см. текст Решения №299)</div>`;
        html+=`<div class="card c-nks" data-dir="im"><div class="rh"><div class="ico">📝</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">Подлежит государственной регистрации (Раздел II)</div><div class="tags"><span class="tag t-nks">📝 Гос. регистрация</span>${hasPartial?'<span class="tag t-nks">⚠️ частичное совпадение</span>':''}</div><div class="det"><div><strong>Наименование:</strong> ${esc(names.slice(0,3).join('; '))}</div><div><strong>Требование:</strong> Свидетельство о государственной регистрации обязательно при первичном производстве/ввозе</div>${hasPartial?'<div><strong>⚠ Внимание:</strong> код найден по совпадению с укрупнённой товарной позицией — из неё может быть исключён ряд конкретных подсубпозиций (см. примечание ниже, если есть)</div>':''}${notesHtml}${sec3Hint}</div></div>`;
      }
      if(exclItems.length>0){
        html+=`<div class="card c-ok"><div class="rh"><div class="ico">✓</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">Госрегистрация не требуется (позиция исключена из Раздела II)</div><div class="tags"><span class="tag t-ok">✓ Исключено</span></div></div>`;
      }
    }
    if(sanRes.sub.length>0){
      const secLabels={mash:'машиностроение/приборостроение/электротехника',hyg:'товары личной гигиены',siz:'СИЗ и материалы для их изготовления',food:'материалы для контакта с пищевыми продуктами',air:'воздухоподготовка/воздухоочистка/фильтрация',med:'изделия медназначения и медтехника'};
      const bySec={};
      sanRes.sub.forEach(e=>{(bySec[e.section]=bySec[e.section]||[]).push(e)});
      const rows=Object.entries(bySec).map(([sec,items])=>{
        const uniq=[...new Map(items.map(e=>[e.name+'|'+(e.note||''),e])).values()];
        const parts=uniq.slice(0,2).map(e=>esc(e.name)+(e.note?` <span class="more-hint">(примечание: ${esc(e.note)})</span>`:''));
        const srcUrl=SAN_SUB_SRC[sec];
        const srcHtml=srcUrl?` · ${docLink('полный текст раздела ЕСТ (нормы по составу/условиям применения)',srcUrl)}`:'';
        return `<div><strong>${esc(secLabels[sec]||sec)}:</strong> ${parts.join('; ')}${srcHtml}</div>`;
      }).join('');
      html+=`<div class="card c-nks" data-dir="im"><div class="rh"><div class="ico">🧪</div><div><div class="rc">${esc(fmtCode(qt))}</div></div></div><div class="rn">Входит в отраслевые перечни Единых санитарных требований (Приложение №2)</div><div class="tags"><span class="tag t-nks">🧪 СЭН — отраслевой перечень</span></div><div class="det">${rows}</div></div>`;
    }
  }

  html=renderWasteBlock(wasteList,qt,html);
  return {cards:true,html};
}

function renderWasteBlock(wasteList,qt,html){
  if(wasteList.length>0){
    const hasExact=wasteList.some(e=>e.exact);
    const hasPartial=wasteList.some(e=>!e.exact);
    const allNames=[...new Set(wasteList.map(e=>e.name))];
    let tags=`<span class="tag t-eec-ex">⛔ Запрет ввоза (опасные отходы)</span>`;
    if(hasPartial) tags+=`<span class="tag t-eec-dual">🔍 Частичное совпадение — проверить по наименованию</span>`;
    const namesJoinW=(names,limit)=>{const shown=names.slice(0,limit);const rest=names.length-shown.length;return esc(shown.join('; '))+(rest>0?` <span class="more-hint">+ ещё ${rest}</span>`:'');};
    html+=`<div class="card c-eec" data-dir="im" data-scope="third"${hasExact?'':' data-partial="1"'}><div class="rh"><div class="ico">☣️</div><div><div class="rc">${esc(norm(qt).slice(0,4))}…</div></div></div><div class="rn">Опасные отходы, запрещённые к ввозу</div><div class="tags">${tags}</div><div class="det"><div><strong>Категория:</strong> ${namesJoinW(allNames,5)}</div><div><strong>Основание:</strong> ${docLink('Решение Коллегии ЕЭК от 21.04.2015 № 30',DOC_SOURCES.eecR30)} · Приложение 1, раздел 1.2</div>${hasPartial?'<div><strong>Важно:</strong> код в перечне даётся как «из» (частичное совпадение) — запрет распространяется не на всю товарную позицию целиком, а на конкретный вид отхода по описанию/физ-хим характеристикам. Проверяйте наименование товара, а не только код</div>':''}<div><strong>Также:</strong> запрет распространяется на транзит; вывоз регулируется отдельным Положением (Приложение №7)</div>${auditNote('waste')}</div></div>`;
  }
  return html;
}


