function findVat0(code){
  const qn=String(code).replace(/\D/g,"");if(qn.length<4)return[];
  return VAT0_DB.filter(r=>r[3].some(k=>qn.startsWith(k)));
}

function vatFreeHits(code){
  const firm=[],cond=[];
  const put=(arr,e)=>{if(!arr.some(x=>x.name===e.name&&x.src===e.src))arr.push(e)};
  for(const e of findLS(code)){
    const p=VATFREE_PARTIAL[String(e.code).replace(/\D/g,'')];
    put(p?cond:firm,{name:e.names,src:'приложение 1 (лекарственные средства)',why:p?'в перечне вместо кода указано «'+p+'», то есть освобождена не вся товарная позиция':''});
  }
  for(const e of findMed(code)){
    const p=VATFREE_PARTIAL[String(e.code).replace(/\D/g,'')];
    put(p?cond:firm,{name:e.name,src:'приложение 2 (медицинские изделия)',why:p?'в перечне вместо кода указано «'+p+'», то есть освобождена не вся товарная позиция':''});
  }
  for(const e of findMat(code)){
    put(cond,{name:e.name,src:'приложение 3 (исходные материалы)',why:'освобождение действует только при импорте для производства ЛС и медизделий'});
  }
  // Ст. 297 ч.1 НК КР сверх перечней ПКМ № 596 (до 23.09.2026 калькулятор их не видел и считал НДС 12%
  // по электромобилю, который таможня выпустила с НДС «условно начислено» — ДТ 41762108/230926/0041592).
  // Коды, записанные в самом Кодексе (ART297_CODES), — освобождение безусловное. Перечни ПКМ КР № 131
  // сюда не входят: они именные («Из 8517 — тифлотехнические средства»), а ключ в базе — префикс позиции,
  // и по коду смартфон становился «освобождён для лиц с ОВЗ»; о них говорит карточка поиска.
  // П.17 (наземные и водные ТС только с электродвигателем: 870240, 870380, 890110) — условно: по ч.2
  // ст.297 нужен перечень КМ, которого в базе нет, и год выпуска до 5 лет. Проверено по действующей
  // редакции реестра 57656 от 06.08.2026 (в ред. Законов по № 262 от 31.12.2025); id редакций в реестре
  // не хронологичны — редакция выбирается по дате, а не по наибольшему id.
  for(const e of findArt297(code)){
    put(firm,{name:e.note,src:'ст. 297 ч.1 НК КР (код указан в самом Кодексе)',why:''});
  }
  // Ставка 0% по решениям КМ (п.2 ст.34¹ НК): без условия и в окне действия — как освобождение по коду;
  // с условием (субъект, цель) или вне сезонного окна — условно: НДС начисляется, предупреждение объясняет.
  {const today=new Date(Date.now()+6*3600e3).toISOString().slice(0,10);
   for(const r of findVat0(code)){
     const now=r[4].some(w=>today>=w[0]&&today<=w[1]),later=r[4].some(w=>today<w[0]);
     if(!now&&!later)continue;
     const src="ставка НДС 0% — "+r[0];
     if(!r[5]&&now)put(firm,{name:r[2],src,why:""});
     else put(cond,{name:r[2],src,why:r[5]?r[6]:"0% действует только в периоды: "+r[4].map(w=>w[0].split("-").reverse().join(".")+"–"+w[1].split("-").reverse().join(".")).join(", ")+"; на дату расчёта не действует"});
   }}
  const d=String(code).replace(/\D/g,'');
  if(/^(870240|870380|890110)/.test(d)){
    put(cond,{name:'Наземные и водные транспортные средства, приводимые в движение исключительно электрическим двигателем (870240, 870380, 890110), и запасные части к ним',
      src:'ст. 297 ч.1 п.17 НК КР (в ред. Законов по № 262 от 31.12.2025)',
      why:'освобождение — для ТС с годом выпуска до 5 лет и согласно перечню КМ по ч.2 ст.297; перечня в базе нет, подтвердите по нему (таможня начисляет НДС условно — строка 5010 «УН» в ДТ)'});
  }
  return {firm:firm,cond:cond};
}
function itemVatFree(code){return vatFreeHits(code).firm.length>0}

// «Кода нет в ЕТТ» — почти всегда не опечатка, а старая номенклатура или
// подсубпозиция, которую ЕТТ разделил. Поэтому сначала смотрим TNVED_MAP, потом
// подбираем ближайшие действующие коды по общему началу: брокеру нужен
// действующий код, а не сообщение о том, что его код плохой.
function specNotFoundHint(codeDigits){
  const m=TNVED_MAP[codeDigits];
  if(m&&m.t&&m.t.length)return 'кода нет в действующем ЕТТ; ему соответствует '+m.t.map(x=>fmtCode(x)).join(', ')+' — укажите действующий код';
  for(let len=codeDigits.length-1;len>=4;len--){
    const p=codeDigits.slice(0,len);
    const cand=[];
    for(const r of ETT_DB){
      if(r[0].startsWith(p)){cand.push(r[0]);if(cand.length>3)break}
    }
    if(cand.length)return 'кода нет в ЕТТ; ближайшие действующие: '+cand.slice(0,4).map(x=>fmtCode(x)).join(', ');
  }
  return 'код не найден в ЕТТ';
}

