function quickActionsHtml(code){
  return `<div class="qa-row"><button type="button" class="qa-btn" onclick="copyCode('${code}',this)">📋 Копировать код</button><button type="button" class="qa-btn" onclick="showInTree('${code}')">🌳 Показать в классификаторе</button></div>`;
}
// ─── Справка: какая ставка ввозной пошлины действует для страны происхождения ───
// Правило для каждой страны взято из текста её решения, а не из пересказа
// (сверено 16.09.2026 по docs.eaeunion.org):
//   ОАЭ — Решение Коллегии ЕЭК №113, п.2: 0% для всех товаров, кроме перечня;
//         по перечню — ставка графика на календарный год; если пошлина по ЕТТ
//         ниже — ЕТТ. Вступает в силу 06.10.2026 (п.4 и карточка портала).
//   Вьетнам — №36, п.2: 0%, кроме перечня, спортивной обуви п.3 и товаров под
//         триггерной мерой. Правила «если ЕТТ ниже» в решении нет.
//   Иран — №1, п.2: 0%, кроме перечня; если пошлина по ЕТТ ниже — ЕТТ.
//         В силе с 15.05.2025.
//   Сербия — №122, п.2: освобождение от пошлины, кроме перечня изъятий.
//   Монголия — №74: льготная ставка только по перечню; если ЕТТ ниже — ЕТТ.
//         В силе с 22.07.2026. Коды вне перечня соглашение не затрагивает.
//   ЕСТП — п.2 и п.3 ст.36 Договора о ЕАЭС: 75% ставки ЕТТ для развивающихся
//         стран и 0% для наименее развитых — только по перечню товаров.
// Страна и соглашение не отменяют друг друга: у Ирана и Монголии действуют и
// соглашение, и ЕСТП, поэтому возвращаются все применимые основания, а
// наименьшую ставку выбирает не функция, а человек с нужным сертификатом.
const LK_IN_FORCE={'ОАЭ':'2026-10-06','Иран':'2025-05-15','Монголия':'2026-07-22'};
const RS_CHEESE=['0406906900','0406907400','0406908600','0406908900','0406909200','0406909300','0406909901','0406909909'];

function lkPct(r){
  const s=String(r);
  return s==='0'?'0%':s.replace(/^(\d+(?:,\d+)?)(?=$|,\s*но|\s+плюс)/,'$1%');
}
// Чисто адвалорная ставка → число; смешанная или специфическая → null.
function lkRateNum(r){
  if(typeof r==='number')return r;
  const m=/^\s*(\d+(?:[.,]\d+)?)\s*%?\s*$/.exec(String(r==null?'':r));
  return m?parseFloat(m[1].replace(',','.')):null;
}
function lkNumTxt(n){return (Math.round(n*1000)/1000).toString().replace('.',',')+'%'}
// Доля от ставки ЕТТ любой формы: масштабируются ведущее число и суммы перед
// «евро»/«долл», а «за 1 кг», «за 1000 шт» и «100% спирта» остаются как есть.
// Для комбинированных ставок это верно: max(k·a, k·s) = k·max(a, s).
function lkScaleRate(r,k){
  const n=lkRateNum(r);
  if(n!==null)return lkNumTxt(n*k);
  const f=x=>(Math.round(parseFloat(x.replace(',','.'))*k*10000)/10000).toString().replace('.',',');
  return lkPct(String(r).replace(/(\d+(?:,\d+)?)(?=\s*(?:евро|долл))|^(\d+(?:,\d+)?)/g,(m,a,b)=>f(a||b)));
}
function lkDateRu(iso){return iso.slice(8,10)+'.'+iso.slice(5,7)+'.'+iso.slice(0,4)}
// Самая длинная строка перечня, код которой — префикс запрошенного кода:
// перечни пишут коды в разрядности акта (4, 6, 8, 9 или 10 знаков).
function lkListRow(db,code){
  let best=null,len=0;
  for(const r of db){
    // Строка под кодом, которого нет в действующем ЕТТ (в перечне ЕЭК «Иран» две строки
    // блока 8807 90 напечатаны как 8803 90), находится по преемнику из TNVED_MAP: без
    // этого код считался «вне перечня» и получал 0% вместо ставки ЕТТ.
    const keys=TNVED_MAP[r[0]]&&!ettPrefixSet().has(r[0])?TNVED_MAP[r[0]].t:[r[0]];
    for(const k of keys)if(code.startsWith(k)&&k.length>len){best=r;len=k.length}
  }
  return best;
}
// Ставка перечня против ставки ЕТТ по правилу «если пошлина по ЕТТ ниже —
// применяется ЕТТ». Сравнить суммы без стоимости и веса можно только для двух
// чисто адвалорных ставок; иначе правило называется словами.
// act — пункт решения с этим правилом; у Вьетнама такого пункта нет, и тогда
// говорится то, что верно всегда: без заявления преференции (без сертификата
// происхождения) товар оформляется по ставке ЕТТ.
function lkLowerOf(listRate,ettRate,act){
  const a=lkRateNum(listRate),b=lkRateNum(ettRate);
  const why=act?'применяется ставка ЕТТ ('+act+')':'без заявления преференции по Соглашению товар оформляется по ставке ЕТТ';
  if(a!==null&&b!==null){
    return b<a
      ?{rate:lkNumTxt(b),note:'ставка перечня '+lkNumTxt(a)+' выше ставки ЕТТ, поэтому '+why}
      :{rate:lkNumTxt(a),note:''};
  }
  return {rate:lkPct(listRate),note:'если пошлина по ставке ЕТТ ('+fmtRate(ettRate)+') получится ниже, '+why};
}

function lkPrefRates(code,ettRate,cty,dateIso){
  const out=[];
  if(!cty)return out;
  const date=dateIso||new Date().toISOString().slice(0,10);
  // Зона свободной торговли СНГ (LK_CIS в checker.js): изъятий у Кыргызской Республики нет — 0% по любому коду.
  if(cty.cis){
    const x=cty.cis,o={rate:'0%',flag:x.flag,who:x.bilateral?'Соглашение о свободной торговле КР–'+x.n:'ЗСТ СНГ ('+x.n+')',basis:'ввозная пошлина не применяется — '+x.act,note:'при подтверждении происхождения: '+x.orig};
    if(date<x.from)o.pending=lkDateRu(x.from);
    out.push(o);
    return out;
  }
  if(!cty.pref)return out;
  const ettTxt=fmtRate(ettRate);
  for(const p of cty.pref){
    const f=p.fta&&p.fta.n;
    if(f==='ОАЭ'){
      const from=LK_IN_FORCE['ОАЭ'];
      // до вступления в силу считаем по первому году графика и говорим, с какой даты
      const on=date>=from?date:from;
      const col=Math.min(Math.max(parseInt(on.slice(0,4),10)-2026,0),7);
      const yearLbl=col===7?'2033 год и последующие':(2026+col)+' год';
      const row=ETT_UAE_DB.find(r=>r[0]===code)||lkListRow(ETT_UAE_DB,code);
      let o;
      if(!row)o={rate:'0%',basis:'код вне перечня — ставка 0% (абз.1 п.2 Решения Коллегии ЕЭК №113)'};
      else{
        const raw=row[2][col];
        if(/^ставка ЕТТ/.test(raw)){
          o={rate:ettTxt,basis:'код в перечне со «ставкой ЕТТ» — льготы нет (Решение №113)'};
          if(/\*\*/.test(raw))o.note='в пределах тарифной квоты по Соглашению при наличии лицензии — 0% (сноска ** к перечню)';
          if(/\*\*\*/.test(row[1]))o.note='слитки: 0% вне зависимости от стоимости при документе о последующей переработке (п.3 Решения №113)';
        }else{
          const low=lkLowerOf(raw,ettRate,'абз.2 п.2 Решения №113');
          o={rate:low.rate,basis:'график Решения №113 на '+yearLbl,note:low.note};
        }
      }
      o.flag='🇦🇪';o.who='ОАЭ';
      if(date<from)o.pending=lkDateRu(from);
      out.push(o);
    }else if(f==='Вьетнам'){
      const trig=TRIGGER_DB.filter(t=>t[5]&&t[1]==='Вьетнам'&&t[0].some(c=>code.startsWith(c)));
      const row=lkListRow(ETT_VN_DB,code);
      let o;
      if(trig.length)o={rate:ettTxt,basis:'действует триггерная защитная мера — льгота временно не применяется (п.2 Решения №36; '+trig[0][3].split('»')[0]+'»)'};
      else if(!row)o={rate:'0%',basis:'код вне перечня — ставка 0% (п.2 Решения Коллегии ЕЭК №36)'};
      else if(row[2]==='ставка ЕТТ')o={rate:ettTxt,basis:'код в перечне со «ставкой ЕТТ» — льготы нет (Решение №36)'};
      else{
        const low=lkLowerOf(row[2],ettRate,'');
        o={rate:low.rate,basis:'ставка перечня к Решению №36',note:low.note};
      }
      const vnotes=o.note?[o.note]:[];
      if(row&&row[3])vnotes.push('строка перечня «из»: относится только к товару «'+trunc(row[1],90)+'»; для иных товаров этого кода — 0%');
      if(row&&row[4]==='***')vnotes.push('спортивная обувь по п.3 Решения №36 — 0% при отметках в сертификате происхождения; иначе ставка перечня');
      o.note=vnotes.join('; ');
      o.flag='🇻🇳';o.who='Вьетнам';
      out.push(o);
    }else if(f==='Иран'){
      const row=lkListRow(ETT_IRAN_DB,code);
      let o;
      if(!row)o={rate:'0%',basis:'код вне перечня — ставка 0% (абз.1 п.2 Решения Коллегии ЕЭК №1)'};
      else if(row[2]==='ставка ЕТТ')o={rate:ettTxt,basis:'код в перечне со «ставкой ЕТТ» — льготы нет (Решение №1)'};
      else{
        const low=lkLowerOf(row[2],ettRate,'абз.2 п.2 Решения №1');
        o={rate:low.rate,basis:'ставка перечня к Решению №1',note:low.note};
      }
      const notes=[];
      if(o.note)notes.push(o.note);
      if(row&&row[5]==='**')notes.push('в пределах тарифной квоты по Соглашению при наличии лицензии — 0% (сноска ** к перечню)');
      if(row&&row[3])notes.push('строка перечня «из»: «'+trunc(row[1],90)+'»; в остальных случаях — 0%');
      o.note=notes.join('; ');
      o.flag='🇮🇷';o.who='Иран';
      out.push(o);
    }else if(f==='Сербия'){
      const rows=findETTRS(code).filter(r=>code.startsWith(r[0])||r.mappedFrom);
      let o;
      if(rows.length){
        o={rate:ettTxt,basis:'код в перечне изъятий из режима свободной торговли (п.2 Решения Коллегии ЕЭК №122)'};
        if(rows[0][3])o.note=rows[0][3];
      }else{
        o={rate:'0%',basis:'освобождение от ввозной пошлины (п.2 Решения Коллегии ЕЭК №122)'};
        if(RS_CHEESE.indexOf(code)>=0)o.note='для этих сыров — только при отметке в графе 8 сертификата происхождения (абз.3 п.2 Решения №122)';
      }
      o.flag='🇷🇸';o.who='Сербия';
      out.push(o);
    }else if(f==='Монголия'){
      const from=LK_IN_FORCE['Монголия'];
      const row=lkListRow(ETT_MN_DB,code);
      if(row){
        // три позиции перечня записаны как «скидка N% от ставки ЕТТ ЕАЭС»
        const disc=/^скидка\s+(\d+)%/.exec(row[2]);
        const low=disc
          ?{rate:lkScaleRate(ettRate,(100-parseInt(disc[1],10))/100),note:row[2]}
          :lkLowerOf(row[2],ettRate,'п.2 Решения Коллегии ЕЭК №74');
        const o={rate:low.rate,basis:'ставка перечня к Решению №74',note:low.note,flag:'🇲🇳',who:'Монголия'};
        if(date<from)o.pending=lkDateRu(from);
        out.push(o);
      }
    }
    if(p.dev||p.ldc){
      const hits=findPref(code).filter(h=>!h.ex.length&&((h.sec===0&&p.dev)||(h.sec===1&&p.ldc)));
      for(const h of hits){
        const rate=h.sec===1?'0%':lkScaleRate(ettRate,0.75);
        out.push({rate:rate,flag:'🌍',who:p.name,
          basis:h.sec===1?'ЕСТП, наименее развитая страна — 0% (п.3 ст.36 Договора о ЕАЭС)':'ЕСТП, развивающаяся страна — 75% от ставки ЕТТ (п.2 ст.36 Договора о ЕАЭС)',
          note:'при соблюдении условий п.65 Правил определения происхождения (сертификат, прямая поставка)'+(h.fn?'; позиция определяется и кодом, и наименованием':'')});
      }
    }
  }
  return out;
}
// Карточка поиска вида по названию (Красная книга КР, СИТЕС).
function speciesHtml(q){
  const qq=(q||'').trim();
  if(!qq)return '';
  const list=findSpecies(qq);
  if(!list.length){
    return `<div class="card c-ok"><div class="rn">🐾 По запросу «${esc(qq)}» вид не найден в Красной книге КР или приложениях СИТЕС</div></div>`;
  }
  const shown=list.slice(0,60);
  let rows='';
  for(const r of shown){
    const [ru,lat,status,kind,note]=r;
    const statusLbl=kind==='СИТЕС'?`Приложение ${esc(status)} СИТЕС`:`Красная книга (${esc(status)})`;
    const noteHtml=note?`<div class="uu" style="color:var(--yellow)">⚠ ${esc(note)}</div>`:'';
    rows+=`<div class="usir-row"><div class="un"><b>${esc(ru)}</b> <span style="color:var(--muted);font-style:italic">${esc(lat)}</span></div><div class="uu">${esc(kind)} · ${statusLbl}</div>${noteHtml}</div>`;
  }
  const more=list.length>shown.length?`<div class="ett-more">Показаны первые ${shown.length} из ${list.length} — уточните запрос</div>`:'';
  const posInfo=(list.some(r=>r[3].startsWith('Красная книга'))?permitOrgByPos('2.8'):null)||(list.some(r=>r[3]==='СИТЕС')?permitOrgByPos('2.7'):null);
  const permitHtml=posInfo?`<div class="det" style="margin-top:6px"><strong>Разрешительный документ (п.${esc(posInfo.pos)} Единого перечня):</strong> оформляет ${esc(posInfo.org)}; уполномоченный орган — ${esc(posInfo.upOrg)}${permitSrcHtml(posInfo.src)}${auditNote('permit')}</div>`:'';
  const hasRB=list.some(r=>r[3].startsWith('Красная книга')),hasCites=list.some(r=>r[3]==='СИТЕС');
  const srcParts=[];
  if(hasRB)srcParts.push(docLink('Положение о Красной книге Кыргызской Республики',DOC_SOURCES.redBookKR));
  if(hasCites)srcParts.push(docLink('Конвенция СИТЕС, приложения I/II/III',DOC_SOURCES.cites));
  const sourcesHtml=srcParts.length?`<div class="det" style="margin-top:6px"><strong>Источник:</strong> ${srcParts.join(' · ')}</div>`:'';
  return `<div class="card c-ex"><div class="rh"><div class="ico">🐾</div><div><div class="rc">${esc(qq)}</div></div></div><div class="rn">Найдено видов: ${list.length}</div><div class="tags"><span class="tag t-ex">🐾 Красная книга / СИТЕС</span></div><div class="usir-list">${rows}</div>${more}<div class="det"><strong>Важно:</strong> вывоз/ввоз видов из Красной книги КР и приложений СИТЕС требует разрешительных документов независимо от кода ТН ВЭД товара.</div>${sourcesHtml}${auditNote('species')}${permitHtml}</div>`;
}
// Строит карточку результатов поиска по наименованию — вызывается из
// render() как запасной вариант, когда запрос не совпал ни с одним кодом.
function nameMatchesHtml(qq,list){
  const shown=list.slice(0,60);
  let rows='';
  for(const r of shown){
    const [code,name,unit,rate]=r;
    rows+=`<div class="usir-row" style="cursor:pointer" onclick="goToCode('${code}')">`
      +`<div class="un"><span style="font-family:var(--mono);color:var(--indigo);font-weight:600">${esc(fmtCode(code))}</span> — ${esc(name)}${notesIconHtml(code)}</div>`
      +`<div class="uu">Ставка: ${esc(String(fmtRate(rate)))}${unit?' · Ед.изм.: '+esc(unit):''}</div></div>`;
  }
  const more=list.length>shown.length?`<div class="ett-more">Показаны первые ${shown.length} из ${list.length} — уточните запрос</div>`:'';
  return `<div class="card c-ett"><div class="rh"><div class="ico">📝</div><div><div class="rc">${esc(qq)}</div></div></div><div class="rn">Найдено товаров по наименованию: ${list.length} — нажмите строку, чтобы открыть карточку кода</div><div class="tags"><span class="tag t-ett">📝 Поиск по наименованию</span></div><div class="usir-list">${rows}</div>${more}</div>`;
}

// ═══════════════════════════════════════════
// ЗАПРОСЫ БРАУЗЕРА К БАЗЕ (/api/engine → ENGINE_API)
// Каждая функция отвечает на один запрос человека: карточки по коду, коды группы,
// сведения о коде для калькулятора. Базу целиком этим путём не получить, а частые и
// широкие запросы сервер ограничивает (server/src/routes/engine.js). Аргументы
// приходят из сети — каждая функция приводит их к ожидаемому виду сама.
// ═══════════════════════════════════════════
function calcCodeList(q){
  const list=findETT(q),qn=norm(q).replace(/\D/g,'');
  return {total:list.length,rows:list.slice(0,60).map(r=>[r[0],r[1],r[3]]),
    exact:list.length===1?list[0][0]:(qn.length>=10&&list.some(r=>r[0]===qn)?qn:null)};
}
// Всё, что калькулятору и партии нужно знать о коде, одним ответом (calcInfo в checker.js).
function codeBundle(codes){
  const out={};
  for(const code of codes){
    const rec=ETT_DB.find(r=>r[0]===code);
    out[code]=rec?{rec:rec,warns:calcWarnings(code),
      pref:findPref(code).filter(p=>!p.ex.length).map(p=>({sec:p.sec})),
      exc:findExcise(code),vf:vatFreeHits(code),
      reqs:BATCH_REQS.map((r,i)=>{let hit=false;try{hit=r.f(code)}catch(e){}return hit?{k:r.k,c:r.c,l:r.l,i:i}:null}).filter(Boolean)}:null;
  }
  return out;
}
// Строка ЕТТ для кода из спецификации, либо число подходящих кодов, либо подсказка.
function specLookup(codes){
  const out={};
  for(const c of codes){
    const list=findETT(c);
    const ett=list.find(x=>x[0]===c)||(list.length===1?list[0]:null);
    out[c]=ett?{ett:ett}:{n:list.length,hint:list.length?'':specNotFoundHint(c)};
  }
  return out;
}
function treeChapter(nn,limit,highlightCode){
  const items=ETT_DB.filter(r=>r[0].startsWith(nn));
  let shown=limit;
  if(highlightCode){
    const idx=items.findIndex(r=>r[0]===highlightCode);
    if(idx>=0&&idx+1>shown)shown=idx+1;
  }
  return {total:items.length,shown:shown,rows:items.slice(0,shown).map(r=>[r[0],r[1],r[3]])};
}
// Ставки для страны происхождения по кодам карточки ЕТТ. Страна разбирается здесь заново
// из введённого текста: объекту страны из браузера сервер не доверяет.
function lkRates(codes,ctyTxt,date){
  const cty=lkCountry(ctyTxt),out={};
  if(!cty||!(cty.pref||cty.cis))return out;
  for(const code of codes){
    const r=ETT_DB.find(x=>x[0]===code);
    const ett=r?r[3]:null;
    out[code]={ett:ett,opts:lkPrefRates(code,ett,cty,date)};
  }
  return out;
}
function engStr(v,max){return typeof v==='string'?v.slice(0,max):''}
function engCodes(a,max,re){return Array.isArray(a)?[...new Set(a.filter(c=>typeof c==='string'&&re.test(c)))].slice(0,max):[]}
function engHas(o,k){return typeof k==='string'&&Object.prototype.hasOwnProperty.call(o,k)}
const ENGINE_API={
  renderHtml:(q,date)=>renderHtml(engStr(q,200),engStr(date,10)),
  speciesHtml:(q)=>speciesHtml(engStr(q,200)),
  sourceAuditHtml:()=>sourceAuditHtml(),
  auditNote:(key)=>engHas(SOURCE_AUDIT,key)?auditNote(key):'',
  calcWarnings:(code)=>/^\d{4,10}$/.test(engStr(code,10))?calcWarnings(code):[],
  calcCodeList:(q)=>calcCodeList(engStr(q,40)),
  codeBundle:(codes)=>codeBundle(engCodes(codes,50,/^\d{10}$/)),
  specLookup:(codes)=>specLookup(engCodes(codes,200,/^\d{1,14}$/)),
  treeChapter:(nn,limit,hl)=>/^\d\d$/.test(engStr(nn,2))?treeChapter(nn,Math.min(Math.max(parseInt(limit,10)||50,1),2000),engStr(hl,10)):{total:0,shown:0,rows:[]},
  lkRates:(codes,cty,date)=>lkRates(engCodes(codes,200,/^\d{10}$/),engStr(cty,100),/^\d{4}-\d\d-\d\d$/.test(engStr(date,10))?date:''),
  autoBrands:()=>Object.keys(AUTO_CALC_IDX).sort(),
  autoModels:(brand)=>engHas(AUTO_CALC_IDX,brand)?Object.keys(AUTO_CALC_IDX[brand]).sort():[],
  autoVariants:(brand,model)=>engHas(AUTO_CALC_IDX,brand)&&engHas(AUTO_CALC_IDX[brand],model)?AUTO_CALC_IDX[brand][model]:[],
};
